/// Compactions in a row the provider has not answered yet: each one after
/// a refusal aims lower ([`overflow_share`]), and more would only summarize
/// the last summary. A request the provider takes starts the count again, so
/// a long turn compacts as often as its growth needs, not a fixed number of
/// times.
const MAX_COMPACTIONS_UNANSWERED: u8 = 4;

/// How much a turn's context must grow after a compaction before it compacts
/// again by itself: a quarter of the size at which compaction starts. Where
/// a summary and the part kept with it leave the context still large, each
/// further summary then covers that much new work, so compacting never costs
/// more than the rounds it makes room for.
const COMPACTION_REGROWTH_DIVISOR: u64 = 4;

/// How a refusal of a request as longer than the model's window begins when
/// the turn had already compacted the chat as often as it may: the turn
/// outgrew the window while it ran (a model reading one large file after
/// another), not its instructions and the person's message. The provider's
/// words follow.
const OUTGREW_WINDOW: &str = "the turn outgrew the model's context after compacting the chat: ";

/// `error` as [`OUTGREW_WINDOW`] says it, when it refuses the request as too
/// long once the turn has compacted `compactions` times in a row without the
/// provider taking a request, as often as it may.
fn outgrew_window(error: CoreError, compactions: u8) -> CoreError {
    match error {
        CoreError::Provider(message)
            if compactions >= MAX_COMPACTIONS_UNANSWERED
                && !message.starts_with(OUTGREW_WINDOW)
                && is_provider_context_overflow(&CoreError::Provider(message.clone())) =>
        {
            CoreError::Provider(format!("{OUTGREW_WINDOW}{message}"))
        }
        other => other,
    }
}

fn latest_todos(items: &[Item], through: Option<u64>) -> Vec<TodoEntry> {
    items
        .iter()
        .rev()
        .find_map(|item| {
            (through.is_none_or(|sequence| item.sequence <= sequence))
                .then_some(&item.data)
                .and_then(|data| match data {
                    ItemData::Todo { items } => Some(items.clone()),
                    _ => None,
                })
        })
        .unwrap_or_default()
}

fn latest_todo_checkpoint(items: &[Item], through: Option<u64>) -> TodoCheckpoint {
    let latest = items.iter().rev().find_map(|item| {
        (through.is_none_or(|sequence| item.sequence <= sequence))
            .then_some(&item.data)
            .and_then(|data| match data {
                ItemData::Todo { items } => Some((item.sequence, items.clone())),
                _ => None,
            })
    });
    let (revision, todos) = latest.unwrap_or((0, Vec::new()));
    TodoCheckpoint {
        version: 1,
        revision,
        todos,
    }
}

/// Raw items which are still visible to the provider after the newest
/// compaction. The summary precedes its retained verbatim tail even though the
/// tail's durable rows necessarily have earlier sequence numbers.
fn provider_visible_items(items: &[Item]) -> Vec<&Item> {
    tokens::visible_items(items)
}

/// `request` completed for a compaction of `items`: the exact task list,
/// and what the compaction keeps beside its summary under `input_limit`
/// (see [`retained`]), with `share` of the room there is for it. Refused,
/// in words for the person, when their latest request cannot fit.
fn complete_compaction_request(
    settings: &crate::CompactionSettings,
    items: &[Item],
    mut request: CompactRequest,
    input_limit: Option<u64>,
    tokenizer: Tokenizer,
    share: f64,
) -> CoreResult<CompactRequest> {
    request.todo_checkpoint = Some(latest_todo_checkpoint(items, None));
    let summary = tokenizer.item(&ItemData::Compaction {
        summary: request.summary.clone().unwrap_or_default(),
        files_touched: request.files_touched.clone(),
        outstanding: request.outstanding.clone(),
        todo_checkpoint: request.todo_checkpoint.clone(),
        tail_start_sequence: None,
        kept_sequences: Vec::new(),
        tool_output_chars: None,
    });
    let budget = retained::Budget::new(settings, items, input_limit, summary, share);
    let plan = retained::plan(items, settings.tail_turns, budget, tokenizer)
        .map_err(|too_long| CoreError::Invalid(too_long.message()))?;
    request.tail_start_sequence = plan.tail_start;
    request.kept_sequences = plan.kept;
    request.tool_output_chars = plan.output_chars;
    Ok(request)
}

/// Refuses a compaction of `items` that could not keep the person's latest
/// request, before a summary is asked for.
fn request_fits(
    settings: &crate::CompactionSettings,
    items: &[Item],
    input_limit: Option<u64>,
    tokenizer: Tokenizer,
    share: f64,
) -> CoreResult<()> {
    let budget = retained::Budget::new(settings, items, input_limit, 0, share);
    match retained::too_long(items, budget, tokenizer) {
        Some(too_long) => Err(CoreError::Invalid(too_long.message())),
        None => Ok(()),
    }
}

/// The share of the room for the kept part a compaction after a provider
/// refused the request as too long takes: the estimate ran low, so each
/// further refusal in one turn aims lower.
fn overflow_share(compactions: u8) -> f64 {
    [0.7, 0.5, 0.35, 0.25][usize::from(compactions.min(3))]
}

/// `share` of `tokens`.
fn scaled(tokens: u64, share: f64) -> u64 {
    #[allow(
        clippy::cast_precision_loss,
        clippy::cast_possible_truncation,
        clippy::cast_sign_loss
    )]
    let scaled = (tokens as f64 * share) as u64;
    scaled
}

fn compaction_input_limit(
    settings: &crate::CompactionSettings,
    context_window: u64,
    model_max_output: Option<u64>,
) -> u64 {
    // When metadata has no output limit, reserve a bounded quarter of the
    // context rather than applying a fixed 32k reserve that would make every
    // small-context model compact immediately.
    let inferred_reserve = model_max_output
        .filter(|value| *value > 0)
        .unwrap_or_else(|| 32_000.min(context_window / 4));
    // Some catalogs list an output limit as large as the window itself; input
    // always keeps at least half, or every round would compact to nothing.
    let reserve = settings
        .reserve_output
        .map_or(inferred_reserve, |configured| {
            configured.max(inferred_reserve)
        })
        .min(context_window / 2);
    let safety_limit = context_window.saturating_sub(reserve);
    #[allow(clippy::cast_precision_loss, clippy::cast_possible_truncation)]
    #[allow(clippy::cast_sign_loss)]
    let threshold_limit = (context_window as f64 * settings.threshold.clamp(0.0, 1.0)) as u64;
    safety_limit.min(threshold_limit)
}

/// The next request's context against the model's limits.
#[derive(Debug, Clone, Copy)]
pub struct ContextUsage {
    pub estimate: tokens::ContextEstimate,
    /// The model's context window, when its metadata states one or the
    /// provider showed a smaller one by refusing a request as too long;
    /// compaction assumes 128k otherwise.
    pub window: Option<u64>,
    /// Automatic compaction starts above this many tokens.
    pub compact_at: u64,
}

/// How the turn that started some work answers approvals, kept by that work
/// (a workflow's thread and agents) after the turn ends. Only work the turn
/// started carries it: a person's own turn or `!` command in such a chat
/// never does.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct RunStance {
    /// The turn approved its own requests once (a schedule, `run --yolo`,
    /// ACP, a `--yolo` terminal UI).
    auto_approve: bool,
    /// Nobody can answer the turn: a schedule's run. A request that needs a
    /// person fails at once instead of waiting.
    unattended: bool,
}

/// Chats a schedule created whose run has not started yet, the stance each
/// workflow thread took from the turn that started it, and the threads a
/// workflow's agents work in (every turn there, a result delivered after
/// the agent's turn too, ends whatever Stop hooks say).
#[derive(Default)]
struct RunStances {
    scheduled: DashMap<ThreadId, ()>,
    started: DashMap<ThreadId, RunStance>,
    workflow_agents: DashMap<ThreadId, ()>,
}

impl RunStances {
    fn of(&self, thread: ThreadId) -> Option<RunStance> {
        self.started.get(&thread).map(|stance| *stance)
    }
}

struct ActiveTurn {
    id: TurnId,
    request_id: RequestId,
    /// Propagated to workflow-owned turns so a headless scheduled run cannot
    /// stall as soon as it delegates work to an agent node.
    auto_approve: bool,
    /// A schedule's run, or work it started: nobody can answer it.
    unattended: bool,
    cancel: CancellationToken,
    /// Queue callers wait for this during both launch setup and terminal
    /// closure rather than mistaking either transient state for a conflict.
    changed: Notify,
    /// Queue append and final no-more-input decision share this gate. A
    /// message either lands before the final snapshot or starts a fresh turn;
    /// it can never be accepted into a turn that has already decided to end.
    accepting: AsyncMutex<bool>,
    /// Why the runtime, not the user, cancelled this turn. A bare cancellation
    /// reads as the user's own stop; a server shutdown must say so.
    stop_reason: Mutex<Option<String>>,
    /// The user stopped this turn and asked for steering it has not read yet
    /// to be answered, rather than dropped (as the end of a scheduled run
    /// that stops it does).
    answer_steer: AtomicBool,
    /// The agent definition the turn runs with. Ceilings for work it starts
    /// (workflow agents, direct tools on its children) come from it, not
    /// from the agent's file as it is now.
    agent: AgentSnapshot,
    /// The turn's calls that have begun since they were made, by call id.
    /// Stop, and a shutdown the turn outlives, say the others never ran:
    /// reads (and delegations) run together, so the first call without a
    /// result is not the only one that began.
    started_calls: Mutex<HashSet<String>>,
}

/// Model-facing prompt for the turn that answers steering the user sent
/// before stopping. The steering itself is already in the history above it.
const STOP_CONTINUATION: &str = "<system-reminder>\nThe user stopped your previous work \
before you read the message they sent while you were working. Reply to that message now. \
Do not resume the stopped work unless the message asks you to.\n</system-reminder>";

/// [`STOP_CONTINUATION`] when the end of a scheduled run stopped the work,
/// not the user.
const RUN_END_CONTINUATION: &str = "<system-reminder>\nThe scheduled run your previous work \
belonged to has ended, and that work was stopped before you read the message the user sent \
while it went on. Answer that message now; take the stopped work up again only if it asks \
for that.\n</system-reminder>";

/// What the model reads before the feedback of a Stop hook that kept its
/// turn going, which follows in a `<hook-feedback>` block.
const STOP_HOOK_FEEDBACK: &str = "Stop hook output follows. A Stop hook runs when you finish \
working; this one objected, so the turn continues. Treat the block as the report of an \
automated check that the person did not type, resolve what it reports, and finish again when \
that is done.";

/// How often in a row Stop hooks may keep one turn going: a hook that
/// always blocks cannot hold a turn forever.
const STOP_HOOK_CONTINUATIONS: u32 = 8;

/// The transcript line for a turn the runtime had to stop.
fn stopped_turn_message(reason: &str) -> String {
    format!(
        "{reason}. Work already recorded is preserved; send a new message to continue. Tools are not replayed automatically."
    )
}

