    #[test]
    fn workflow_starts_once_and_status_can_be_observed_once_per_run_and_turn() {
        let observations = parking_lot::Mutex::new(std::collections::HashSet::new());
        assert!(super::workflow_call_guard(&observations, &json!({"action":"start"})).is_none());
        let retry = super::workflow_call_guard(&observations, &json!({"action":"start"}))
            .expect("successive starts are blocked");
        assert!(retry.contains("successive workflows is disabled"));
        let first =
            super::workflow_call_guard(&observations, &json!({"action":"wait", "runID":"run-a"}));
        assert!(first.is_none());
        let repeated = super::workflow_call_guard(
            &observations,
            &json!({"action":"inspect", "runID":"run-a"}),
        )
        .expect("repeat polling is blocked");
        assert!(repeated.contains("Further polling is disabled"));
        assert!(
            super::workflow_call_guard(
                &observations,
                &json!({"action":"inspect", "runID":"run-b"}),
            )
            .is_none(),
            "a different workflow remains observable"
        );
        assert!(
            super::workflow_call_guard(
                &observations,
                &json!({"action":"cancel", "runID":"run-a"}),
            )
            .is_none(),
            "lifecycle controls are not polling"
        );
    }

    #[test]
    fn compaction_metadata_prefers_exact_then_longest_prefix_in_any_order() {
        let short = model_info("gemini", 32_000);
        let specific = model_info("gemini-2.5-pro", 1_000_000);

        let models = vec![short.clone(), specific.clone()];
        assert_eq!(
            super::model_metadata(&models, "gemini-2.5-pro").and_then(|info| info.context_window),
            Some(1_000_000),
            "an exact model id wins over every prefix"
        );
        assert_eq!(
            super::model_metadata(&models, "gemini-2.5-pro-20260824")
                .and_then(|info| info.context_window),
            Some(1_000_000),
            "the most specific catalog prefix wins"
        );

        let reversed = vec![specific, short];
        assert_eq!(
            super::model_metadata(&reversed, "gemini-2.5-pro-20260824")
                .and_then(|info| info.context_window),
            Some(1_000_000),
            "selection cannot depend on provider iteration order"
        );

        let lookalike = vec![model_info("gpt-5", 400_000)];
        assert!(
            super::model_metadata(&lookalike, "gpt-50").is_none(),
            "a lexical prefix without a model-id boundary is not a match"
        );
    }

    #[test]
    fn ultracode_uses_advertised_max_but_caps_claude_at_xhigh() {
        let mut generic = model_info("reasoner", 128_000);
        generic.reasoning = true;
        generic.reasoning_efforts = ["low", "high", "xhigh", "max"].map(str::to_owned).to_vec();
        assert_eq!(
            super::ultracode_reasoning_effort(&[generic], "custom", "reasoner").as_deref(),
            Some("max")
        );

        let mut claude = model_info("claude-next", 1_000_000);
        claude.reasoning = true;
        claude.reasoning_efforts = ["high", "xhigh", "max"].map(str::to_owned).to_vec();
        assert_eq!(
            super::ultracode_reasoning_effort(&[claude], "anthropic", "claude-next").as_deref(),
            Some("xhigh")
        );

        let mut provider_default = model_info("opaque-reasoner", 128_000);
        provider_default.reasoning = true;
        assert!(
            super::ultracode_reasoning_effort(&[provider_default], "custom", "opaque-reasoner")
                .is_none()
        );

        // A level this release does not know is the strongest a model has
        // only when it lists nothing at max.
        let mut newer = model_info("reasoner-2", 128_000);
        newer.reasoning = true;
        newer.reasoning_efforts = ["low", "high", "ultra"].map(str::to_owned).to_vec();
        assert_eq!(
            super::ultracode_reasoning_effort(&[newer.clone()], "custom", "reasoner-2").as_deref(),
            Some("ultra")
        );
        newer.reasoning_efforts = ["low", "max", "ultra"].map(str::to_owned).to_vec();
        assert_eq!(
            super::ultracode_reasoning_effort(&[newer], "custom", "reasoner-2").as_deref(),
            Some("max")
        );
    }

    #[test]
    fn ordinary_openai_gpt5_requests_visible_balanced_reasoning() {
        let mut gpt = model_info("gpt-5.6", 400_000);
        gpt.reasoning = true;
        gpt.reasoning_efforts = ["none", "low", "medium", "high"]
            .map(str::to_owned)
            .to_vec();
        assert_eq!(
            super::default_visible_reasoning_effort(&[gpt.clone()], "openai", "gpt-5.6").as_deref(),
            Some("medium")
        );
        assert!(
            super::default_visible_reasoning_effort(&[gpt.clone()], "custom", "gpt-5.6").is_none(),
            "custom providers retain their own default"
        );

        gpt.reasoning_efforts = ["low", "high"].map(str::to_owned).to_vec();
        assert!(
            super::default_visible_reasoning_effort(&[gpt], "openai", "gpt-5.6").is_none(),
            "never send an effort the provider did not advertise"
        );

        let mut pro = model_info("gpt-5-pro", 400_000);
        pro.reasoning = true;
        pro.reasoning_efforts = ["high"].map(str::to_owned).to_vec();
        assert!(
            super::default_visible_reasoning_effort(&[pro], "openai", "gpt-5-pro").is_none(),
            "a model that lists no medium keeps its provider default"
        );

        // A model released after this build follows its catalog entry, not
        // its id.
        for id in ["gpt-7", "o9-mini", "astra-2"] {
            let mut later = model_info(id, 400_000);
            later.reasoning = true;
            later.reasoning_efforts = ["low", "medium", "high", "ultra"]
                .map(str::to_owned)
                .to_vec();
            assert_eq!(
                super::default_visible_reasoning_effort(&[later], "openai", id).as_deref(),
                Some("medium"),
                "{id}"
            );
        }
    }

    #[test]
    fn ultracode_keyword_uses_unicode_identifier_boundaries_and_skips_the_command() {
        assert!(super::detects_ultracode_keyword("please ultracode this"));
        assert!(super::detects_ultracode_keyword("ULTRACODE: audit"));
        for text in [
            "ultracodex",
            "ultracode2",
            "ultracode_mode",
            "öultracode",
            "ultracodeö",
            "/ultracode audit",
        ] {
            assert!(
                !super::detects_ultracode_keyword(text),
                "{text:?} is not a one-turn keyword"
            );
        }
    }

    #[test]
    fn subagent_threads_use_the_task_prompt_as_their_identity() {
        assert_eq!(
            subagent_title("  audit the API boundary  ", "general"),
            "audit the API boundary"
        );
        assert_eq!(subagent_title(" \n\t", "plan"), "plan agent");
        assert_eq!(
            subagent_title("\u{1b}]0;owned\u{7}audit\u{1b}[2J the API", "general"),
            "audit the API"
        );
        assert_eq!(subagent_title("\u{1b}[2J", "plan"), "plan agent");
        assert!(
            subagent_title(
                "one two three four five six seven eight nine ten eleven twelve thirteen",
                "general"
            )
            .ends_with('…')
        );
    }

    fn item(sequence: u64, data: ItemData) -> Item {
        Item {
            id: ItemId::new(),
            thread_id: ThreadId::new(),
            turn_id: None,
            sequence,
            data,
            created_at: Utc::now(),
        }
    }

    #[test]
    fn malformed_tool_history_does_not_poison_later_provider_requests() {
        let messages = provider_messages(vec![
            item(
                1,
                ItemData::ToolCall {
                    call_id: String::new(),
                    name: String::new(),
                    arguments: json!({"path": "."}),
                    provider_metadata: serde_json::Value::Null,
                },
            ),
            item(
                2,
                ItemData::ToolResult {
                    call_id: String::new(),
                    name: String::new(),
                    output: "tool error".into(),
                    is_error: true,
                    metadata: serde_json::Value::Null,
                },
            ),
            item(
                3,
                ItemData::UserMessage {
                    text: "continue".into(),
                    attachments: Vec::new(),
                    queued: false,
                    synthetic: false,
                    command_line: None,
                    hook: None,
                },
            ),
        ]);

        assert_eq!(messages.len(), 1);
        assert!(matches!(
            &messages[0],
            ProviderMessage::Text { role, content }
                if role == "user" && content == "continue"
        ));
    }

    #[test]
    fn provider_messages_truncate_at_the_last_compaction() {
        let messages = provider_messages(vec![
            item(
                1,
                ItemData::UserMessage {
                    text: "ancient history".into(),
                    attachments: Vec::new(),
                    queued: false,
                    synthetic: false,
                    command_line: None,
                    hook: None,
                },
            ),
            item(
                2,
                ItemData::AssistantMessage {
                    text: "ancient answer".into(),
                },
            ),
            item(
                3,
                ItemData::Compaction {
                    summary: "everything so far".into(),
                    files_touched: Vec::new(),
                    outstanding: Vec::new(),
                    todo_checkpoint: None,
                    tail_start_sequence: None,
                    kept_sequences: Vec::new(),
                    tool_output_chars: None,
                },
            ),
            item(
                4,
                ItemData::UserMessage {
                    text: "fresh question".into(),
                    attachments: Vec::new(),
                    queued: false,
                    synthetic: false,
                    command_line: None,
                    hook: None,
                },
            ),
        ]);

        assert_eq!(messages.len(), 2, "history before the summary is dropped");
        assert!(matches!(
            &messages[0],
            ProviderMessage::Text { role, content }
                if role == "user" && content.contains("everything so far")
        ));
        assert!(matches!(
            &messages[1],
            ProviderMessage::Text { content, .. } if content == "fresh question"
        ));
    }

    /// A Stop hook's message stays in the request that answers it, and in
    /// later turns once answered; one its turn never answered (a stop came
    /// first) is left out of the turns after it.
    #[test]
    fn a_stop_hooks_message_its_turn_never_answered_stays_out_of_later_turns() {
        let (first, second) = (Some(TurnId::new()), Some(TurnId::new()));
        let at = |sequence: u64, turn: Option<TurnId>, data: ItemData| Item {
            turn_id: turn,
            ..item(sequence, data)
        };
        let user = |text: &str, hook: Option<&str>| ItemData::UserMessage {
            text: text.into(),
            attachments: Vec::new(),
            queued: false,
            synthetic: hook.is_some(),
            command_line: None,
            hook: hook.map(str::to_owned),
        };
        let reply = |text: &str| ItemData::AssistantMessage { text: text.into() };
        let texts = |items: Vec<Item>| -> Vec<String> {
            provider_messages(items)
                .into_iter()
                .filter_map(|message| match message {
                    ProviderMessage::Text { content, .. } => Some(content),
                    _ => None,
                })
                .collect()
        };
        let asked = vec![
            at(1, first, user("fix it", None)),
            at(2, first, reply("Fixed.")),
            at(3, first, user("HOOK", Some("Stop"))),
        ];
        // The round that answers it reads it.
        assert_eq!(texts(asked.clone()), ["fix it", "Fixed.", "HOOK"]);
        // Answered, it stays for later turns.
        let mut answered = asked.clone();
        answered.push(at(4, first, reply("Tests pass.")));
        answered.push(at(5, second, user("next", None)));
        assert_eq!(
            texts(answered),
            ["fix it", "Fixed.", "HOOK", "Tests pass.", "next"]
        );
        // Stopped before any answer, the next turn never reads it.
        let mut stopped = asked;
        stopped.push(at(
            4,
            first,
            ItemData::Error {
                message: "operation cancelled".into(),
                retryable: false,
            },
        ));
        stopped.push(at(5, second, user("something else", None)));
        assert_eq!(texts(stopped), ["fix it", "Fixed.", "something else"]);
    }

    #[test]
    fn provider_messages_leave_out_whitespace_only_text() {
        let user = |text: &str| ItemData::UserMessage {
            text: text.into(),
            attachments: Vec::new(),
            queued: false,
            synthetic: false,
            command_line: None,
            hook: None,
        };
        let messages = provider_messages(vec![
            item(1, user("read the file")),
            // The line breaks a model streams before its tool call.
            item(
                2,
                ItemData::AssistantMessage {
                    text: "\n\n".into(),
                },
            ),
            item(
                3,
                ItemData::ToolCall {
                    call_id: "call-1".into(),
                    name: "read".into(),
                    arguments: json!({"path": "a.txt"}),
                    provider_metadata: serde_json::Value::Null,
                },
            ),
            item(
                4,
                ItemData::ToolResult {
                    call_id: "call-1".into(),
                    name: "read".into(),
                    output: "contents".into(),
                    is_error: false,
                    metadata: serde_json::Value::Null,
                },
            ),
            item(
                5,
                ItemData::AssistantMessage {
                    text: "Done.".into(),
                },
            ),
            // Saved before turns refused a blank message.
            item(6, user("  \n ")),
            item(7, user("thanks")),
        ]);

        let texts = messages
            .iter()
            .filter_map(|message| match message {
                ProviderMessage::Text { content, .. } => Some(content.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(texts, ["read the file", "Done.", "thanks"]);
        assert_eq!(messages.len(), 5, "the tool call and its result stay");
    }

    fn in_turn(sequence: u64, turn: Option<TurnId>, data: ItemData) -> Item {
        Item {
            turn_id: turn,
            ..item(sequence, data)
        }
    }

    fn person(text: &str, queued: bool) -> ItemData {
        ItemData::UserMessage {
            text: text.into(),
            attachments: Vec::new(),
            queued,
            synthetic: false,
            command_line: None,
            hook: None,
        }
    }

    fn sleep_call(call_id: &str) -> ItemData {
        ItemData::ToolCall {
            call_id: call_id.into(),
            name: "bash".into(),
            arguments: json!({"command": "sleep 120"}),
            provider_metadata: serde_json::Value::Null,
        }
    }

    fn slept(call_id: &str) -> ItemData {
        ItemData::ToolResult {
            call_id: call_id.into(),
            name: "bash".into(),
            output: "slept".into(),
            is_error: false,
            metadata: serde_json::Value::Null,
        }
    }

    /// Each message as one line: `user: …`, `call id`, `result id: …`.
    fn outline(messages: &[ProviderMessage]) -> Vec<String> {
        messages
            .iter()
            .map(|message| match message {
                ProviderMessage::Text { role, content } => format!("{role}: {content}"),
                ProviderMessage::ToolCall { call_id, .. } => format!("call {call_id}"),
                ProviderMessage::ToolResult {
                    call_id,
                    output,
                    is_error,
                    ..
                } => format!(
                    "result {call_id}{}: {output}",
                    if *is_error { " (error)" } else { "" }
                ),
                media @ ProviderMessage::Media { .. } => format!("{media:?}"),
            })
            .collect()
    }

    #[test]
    fn a_call_a_stopped_turn_left_without_a_result_ends_before_the_next_turn() {
        let (stopped, next) = (Some(TurnId::new()), Some(TurnId::new()));
        let unfinished = format!("result b (error): {}", crate::UNFINISHED_CALL_RESULT);
        let messages = provider_messages(vec![
            in_turn(1, stopped, person("run both", false)),
            in_turn(2, stopped, sleep_call("a")),
            in_turn(3, stopped, sleep_call("b")),
            in_turn(4, stopped, slept("a")),
            // What recovery records: no result, only the turn's notice.
            in_turn(
                5,
                stopped,
                ItemData::Error {
                    message: "restarted".into(),
                    retryable: true,
                },
            ),
            in_turn(6, next, person("and now?", false)),
        ]);
        assert_eq!(
            outline(&messages),
            [
                "user: run both",
                "call a",
                "call b",
                "result a: slept",
                unfinished.as_str(),
                "user: and now?",
            ]
        );
    }

    #[test]
    fn a_call_copied_into_a_fork_without_its_result_ends_before_the_next_message() {
        // A fork made before forks left such calls out: its items carry no
        // turn, and the person's messages there are its turns.
        let unfinished = format!("result call-1 (error): {}", crate::UNFINISHED_CALL_RESULT);
        let messages = provider_messages(vec![
            item(1, person("sleep a while", false)),
            item(2, sleep_call("call-1")),
            item(3, person("hi", false)),
        ]);
        assert_eq!(
            outline(&messages),
            [
                "user: sleep a while",
                "call call-1",
                unfinished.as_str(),
                "user: hi"
            ]
        );
        // The fork's own next turn ends it the same way.
        let messages = provider_messages(vec![
            item(1, person("sleep a while", false)),
            item(2, sleep_call("call-1")),
            in_turn(3, Some(TurnId::new()), person("hi", false)),
        ]);
        assert_eq!(outline(&messages)[2], unfinished);
    }

    #[test]
    fn a_second_result_for_one_call_is_not_sent() {
        let (stopped, next) = (Some(TurnId::new()), Some(TurnId::new()));
        let messages = provider_messages(vec![
            in_turn(1, stopped, person("run it", false)),
            in_turn(2, stopped, sleep_call("a")),
            // The shutdown's result, then the stopped turn's own.
            in_turn(
                3,
                stopped,
                ItemData::ToolResult {
                    call_id: "a".into(),
                    name: "bash".into(),
                    output: crate::UNFINISHED_CALL_RESULT.into(),
                    is_error: true,
                    metadata: json!({"unfinished": true}),
                },
            ),
            in_turn(4, stopped, slept("a")),
            in_turn(5, next, person("and now?", false)),
        ]);
        let unfinished = format!("result a (error): {}", crate::UNFINISHED_CALL_RESULT);
        assert_eq!(
            outline(&messages),
            [
                "user: run it",
                "call a",
                unfinished.as_str(),
                "user: and now?"
            ]
        );
    }

    #[test]
    fn a_running_turn_keeps_its_calls_as_they_are() {
        let (earlier, live) = (Some(TurnId::new()), Some(TurnId::new()));
        let items = vec![
            in_turn(1, earlier, person("first", false)),
            in_turn(2, earlier, sleep_call("call-1")),
            in_turn(3, earlier, slept("call-1")),
            in_turn(4, live, person("second", false)),
            // Same id as the earlier turn's call, still running, with a
            // steer queued while it runs.
            in_turn(5, live, sleep_call("call-1")),
            in_turn(6, live, person("also check the logs", true)),
            // Recovery of an earlier turn's background task can write in
            // the chat while this one runs.
            in_turn(
                7,
                earlier,
                ItemData::UserMessage {
                    text: "background result".into(),
                    attachments: Vec::new(),
                    queued: true,
                    synthetic: true,
                    command_line: None,
                    hook: None,
                },
            ),
        ];
        let messages = provider_messages(items);
        assert_eq!(
            outline(&messages)[..5],
            [
                "user: first",
                "call call-1",
                "result call-1: slept",
                "user: second",
                "call call-1",
            ]
        );
        assert!(
            !outline(&messages)
                .iter()
                .any(|line| line.contains(crate::UNFINISHED_CALL_RESULT)),
            "{messages:?}"
        );
    }

    #[test]
    fn compaction_retains_recent_turns_and_exact_todos() {
        let checkpoint = TodoCheckpoint {
            version: 1,
            revision: 4,
            todos: vec![TodoEntry {
                content: "preserve {this} as data".into(),
                status: "in_progress".into(),
                priority: "high".into(),
            }],
        };
        let messages = provider_messages(vec![
            item(
                1,
                ItemData::UserMessage {
                    text: "ancient history".into(),
                    attachments: Vec::new(),
                    queued: false,
                    synthetic: false,
                    command_line: None,
                    hook: None,
                },
            ),
            item(
                2,
                ItemData::AssistantMessage {
                    text: "ancient answer".into(),
                },
            ),
            item(
                3,
                ItemData::UserMessage {
                    text: "recent exact prompt".into(),
                    attachments: Vec::new(),
                    queued: false,
                    synthetic: false,
                    command_line: None,
                    hook: None,
                },
            ),
            item(
                4,
                ItemData::Todo {
                    items: checkpoint.todos.clone(),
                },
            ),
            item(
                5,
                ItemData::AssistantMessage {
                    text: "recent exact answer".into(),
                },
            ),
            item(
                6,
                ItemData::Compaction {
                    summary: "anchored summary".into(),
                    files_touched: vec!["src/main.rs".into()],
                    outstanding: vec!["run tests".into()],
                    todo_checkpoint: Some(checkpoint),
                    tail_start_sequence: Some(3),
                    kept_sequences: Vec::new(),
                    tool_output_chars: None,
                },
            ),
            item(
                7,
                ItemData::UserMessage {
                    text: "fresh question".into(),
                    attachments: Vec::new(),
                    queued: false,
                    synthetic: false,
                    command_line: None,
                    hook: None,
                },
            ),
        ]);

        let text = messages
            .iter()
            .filter_map(|message| match message {
                ProviderMessage::Text { content, .. } => Some(content.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(text.len(), 4);
        assert!(text[0].contains("anchored summary"));
        assert!(text[0].contains("todo-checkpoint"));
        assert!(text[0].contains("preserve {this} as data"));
        assert_eq!(text[1], "recent exact prompt");
        assert_eq!(text[2], "recent exact answer");
        assert_eq!(text[3], "fresh question");
        assert!(!text.iter().any(|content| content.contains("ancient")));
    }

    #[test]
    fn repeated_compaction_keeps_only_the_latest_anchor() {
        let messages = provider_messages(vec![
            item(
                1,
                ItemData::UserMessage {
                    text: "first".into(),
                    attachments: Vec::new(),
                    queued: false,
                    synthetic: false,
                    command_line: None,
                    hook: None,
                },
            ),
            item(
                2,
                ItemData::Compaction {
                    summary: "old anchor".into(),
                    files_touched: Vec::new(),
                    outstanding: Vec::new(),
                    todo_checkpoint: None,
                    tail_start_sequence: Some(1),
                    kept_sequences: Vec::new(),
                    tool_output_chars: None,
                },
            ),
            item(
                3,
                ItemData::UserMessage {
                    text: "second".into(),
                    attachments: Vec::new(),
                    queued: false,
                    synthetic: false,
                    command_line: None,
                    hook: None,
                },
            ),
            item(
                4,
                ItemData::Compaction {
                    summary: "new anchor".into(),
                    files_touched: Vec::new(),
                    outstanding: Vec::new(),
                    todo_checkpoint: Some(TodoCheckpoint {
                        version: 1,
                        revision: 0,
                        todos: Vec::new(),
                    }),
                    tail_start_sequence: Some(3),
                    kept_sequences: Vec::new(),
                    tool_output_chars: None,
                },
            ),
        ]);
        let joined = messages
            .iter()
            .filter_map(|message| match message {
                ProviderMessage::Text { content, .. } => Some(content.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("\n");
        assert!(joined.contains("new anchor"));
        assert!(joined.contains("second"));
        assert!(joined.contains("\"todos\":[]"));
        assert!(!joined.contains("old anchor"));
        assert!(!joined.contains("first"));
    }

    #[test]
    fn bedrock_refusals_are_retried_or_explained_in_its_own_words() {
        let provider = |message: &str| CoreError::Provider(message.into());
        // Throttling per minute backs off; a daily allowance fails at once.
        let throttled = provider(
            "HTTP 429 Too Many Requests: [ThrottlingException] Too many requests, please wait before trying again.",
        );
        assert_eq!(
            super::retry_delay(&throttled, 2),
            Some(std::time::Duration::from_secs(4))
        );
        let daily = provider(
            "HTTP 429 Too Many Requests: [ThrottlingException] Too many tokens per day, please wait before trying again.",
        );
        assert!(super::retry_delay(&daily, 1).is_none());
        assert_eq!(
            super::describe_error(&daily, Some("Amazon Bedrock")),
            "Amazon Bedrock rate limit or quota reached: Too many tokens per day, please wait before trying again."
        );
        assert!(
            super::retry_delay(
                &provider("HTTP 503 Service Unavailable: [ServiceUnavailableException] Bedrock is unable to process your request."),
                1
            )
            .is_some()
        );
        assert_eq!(
            super::describe_error(
                &provider(
                    "HTTP 403 Forbidden: [AccessDeniedException] Authentication failed: Please make sure your API Key is valid."
                ),
                Some("Amazon Bedrock")
            ),
            "Amazon Bedrock rejected the API key or sign-in (Authentication failed: Please make sure your API Key is valid). Connect Amazon Bedrock again to replace it."
        );
        // A model the account may not use is the request's refusal, not the key's.
        assert_eq!(
            super::describe_error(
                &provider(
                    "HTTP 403 Forbidden: [AccessDeniedException] anthropic.claude-haiku-5-5 is not available for this account."
                ),
                Some("Amazon Bedrock")
            ),
            "Amazon Bedrock rejected the request: anthropic.claude-haiku-5-5 is not available for this account."
        );
        // The AWS sign-in on this machine gave no credentials: said as is,
        // naming the profile and what to run, not as a provider error.
        let sign_in = "Amazon Bedrock could not get AWS credentials for the AWS profile corp: Token has expired and refresh failed. If the profile signs in through AWS IAM Identity Center, run `aws sso login --profile corp` and try again.";
        assert_eq!(
            super::describe_error(&provider(sign_in), Some("Amazon Bedrock")),
            sign_in
        );
    }

    #[test]
    fn a_tool_call_the_provider_could_not_read_is_asked_for_again_then_said_plainly() {
        let unreadable =
            |reason: &str| CoreError::Provider(format!("{}{reason}", crate::UNREADABLE_TOOL_CALL));
        // Written wrong: asked for again, with the reason.
        let wrong =
            unreadable("error parsing tool call: invalid character 'd' in string escape code");
        let note = super::refused_tool_call(&wrong).unwrap();
        assert!(note.starts_with(super::UNREADABLE_CALL), "{note}");
        assert!(note.ends_with("invalid character 'd' in string escape code"));
        assert_eq!(
            super::describe_error(&wrong, Some("Ollama")),
            "Ollama couldn't read the model's tool calls, even after the model was asked to write them again. Send the message again, or choose another model."
        );
        // Broken off before it ended (or where the reply filled the
        // context): in full, or in smaller calls.
        for reason in [
            "error parsing tool call: unexpected end of JSON input",
            "XML syntax error on line 9: unexpected EOF",
            "incomplete GLM tool call: missing </tool_call>",
        ] {
            let cut = unreadable(reason);
            assert_eq!(
                super::refused_tool_call(&cut).as_deref(),
                Some(super::CUT_CALL)
            );
            assert!(
                super::describe_error(&cut, Some("Ollama"))
                    .starts_with("The model's tool calls kept breaking off"),
            );
        }
        // Groq's refusal reads as it did.
        let groq = CoreError::Provider("HTTP 400 Bad Request: [tool_use_failed] Tool call validation failed: parameters for tool read did not match schema".into());
        assert!(
            super::refused_tool_call(&groq)
                .unwrap()
                .starts_with(super::REFUSED_CALL)
        );
        assert!(super::unreadable_tool_call(&groq).is_none());
    }

    #[test]
    fn a_picture_refused_for_a_model_without_vision_reads_as_advice() {
        // Every refusal the provider adapters write (haarness-providers
        // `media::Unreadable::stand_in` and the Chat Completions audio one).
        for refusal in [
            "GLM-5.1 doesn't read images. Send the message without the picture, or switch to a model that reads them.",
            "Haarness can't send audio to Claude Sonnet 5.5. Send the message without the recording, or switch to a model that takes audio.",
            "Haarness can't send video to GPT-6.1 Sol. Send the message without the video, or switch to a model that takes video.",
            "Haarness can't send notes.bin to gpt-oss-120b. Send the message without the file, or switch to another model.",
            // A file's name is not a network or timeout fault.
            "Haarness can't send dns-capture.pcap to gpt-oss-120b. Send the message without the file, or switch to another model.",
            "Haarness can't send timeout-trace.bin to gpt-oss-120b. Send the message without the file, or switch to another model.",
            "Haarness can send Voxtral Small audio only as MP3 or WAV. Send the message without the recording, or with it as MP3 or WAV.",
        ] {
            let refused = CoreError::Provider(refusal.into());
            assert_eq!(
                super::describe_failure(&refused, Some("Z.AI"), true),
                refusal
            );
            assert_eq!(super::describe_error(&refused, Some("Z.AI")), refusal);
        }
        // A provider's own refusal that happens to say it is still the
        // provider's.
        let relayed = CoreError::Provider(
            "HTTP 400 Bad Request: images are off. Send the message without the picture.".into(),
        );
        assert_eq!(
            super::describe_error(&relayed, Some("Z.AI")),
            "Z.AI rejected the request: images are off. Send the message without the picture."
        );
    }

