    fn glob_and_grep_permissions_match_the_search_pattern_not_the_path() {
        let glob = super::ask_plans(
            "glob",
            &json!({"pattern":"**/*.rs","path":"src"}),
            std::path::Path::new("/workspace"),
        );
        assert_eq!(glob.last().unwrap().permission, "glob");
        assert_eq!(glob.last().unwrap().patterns, vec!["**/*.rs"]);

        let grep = super::ask_plans(
            "grep",
            &json!({"pattern":"unsafe","path":"src"}),
            std::path::Path::new("/workspace"),
        );
        assert_eq!(grep.last().unwrap().permission, "grep");
        assert_eq!(grep.last().unwrap().patterns, vec!["unsafe"]);
    }

    #[test]
    fn file_permissions_also_meet_the_rules_for_the_file_really_opened() {
        let workspace =
            std::env::temp_dir().join(format!("haarness-real-path-{}", uuid::Uuid::now_v7()));
        std::fs::create_dir_all(workspace.join("node_modules/pkg")).unwrap();
        std::fs::write(workspace.join(".env"), "fixture").unwrap();
        std::fs::write(workspace.join("node_modules/pkg/.env"), "fixture").unwrap();
        std::fs::write(workspace.join("main.rs"), "fixture").unwrap();
        #[cfg(unix)]
        std::os::unix::fs::symlink(".env", workspace.join("notes.txt")).unwrap();
        let engine = crate::PermissionEngine::build_defaults();
        let read = |path: &str| {
            let plan = super::ask_plans("read", &json!({"path": path}), &workspace).remove(0);
            assert_eq!(plan.permission, "read");
            assert_eq!(plan.always, plan.patterns, "{path}");
            let asks = plan.patterns.iter().any(|pattern| {
                engine.evaluate(&plan.operation(pattern)) == crate::PermissionDecision::Ask
            });
            (plan.patterns, asks)
        };
        // A plain path is checked as written, once.
        assert_eq!(read("main.rs"), (vec!["main.rs".to_owned()], false));
        assert_eq!(read(".env"), (vec![".env".to_owned()], true));
        assert_eq!(read("./main.rs"), (vec!["./main.rs".to_owned()], false));
        // Files inside node_modules are read without asking...
        assert_eq!(
            read("node_modules/pkg/.env"),
            (vec!["node_modules/pkg/.env".to_owned()], false)
        );
        // ...but `..` cannot make the project's .env look like one of them.
        for path in ["node_modules/pkg/../../.env", "node_modules/../.env"] {
            assert_eq!(read(path), (vec![path.to_owned(), ".env".to_owned()], true));
        }
        let absolute = workspace.join("node_modules/../.env");
        let (patterns, asks) = read(absolute.to_str().unwrap());
        assert!(asks);
        assert_eq!(
            patterns[1],
            crate::paths::canonicalize(&workspace)
                .unwrap()
                .join(".env")
                .display()
                .to_string()
        );
        // A link is checked by its target too, and edits through it as well.
        #[cfg(unix)]
        {
            assert_eq!(
                read("notes.txt"),
                (vec!["notes.txt".to_owned(), ".env".to_owned()], true)
            );
            for (tool, args) in [
                ("edit", json!({"path":"notes.txt","old":"a","new":"b"})),
                ("write", json!({"path":"notes.txt","content":"b"})),
            ] {
                let plan = super::ask_plans(tool, &args, &workspace).remove(0);
                assert_eq!(plan.permission, "edit");
                assert_eq!(plan.patterns, vec!["notes.txt", ".env"]);
                assert_eq!(plan.always, vec!["*"]);
            }
        }
        std::fs::remove_dir_all(workspace).unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn a_list_or_a_new_workflow_through_a_link_meets_the_rules_for_where_it_leads() {
        let workspace =
            std::env::temp_dir().join(format!("haarness-linked-list-{}", uuid::Uuid::now_v7()));
        std::fs::create_dir_all(workspace.join("build")).unwrap();
        std::fs::create_dir_all(workspace.join("private/flows")).unwrap();
        std::fs::create_dir_all(workspace.join(".haarness")).unwrap();
        std::os::unix::fs::symlink("build", workspace.join("alias")).unwrap();
        std::os::unix::fs::symlink("../private/flows", workspace.join(".haarness/workflows"))
            .unwrap();
        let mut engine = crate::PermissionEngine::new(vec![
            crate::PermissionRule {
                pattern: "*".into(),
                decision: crate::PermissionDecision::Allow,
            },
            crate::PermissionRule {
                pattern: "list:build".into(),
                decision: crate::PermissionDecision::Deny,
            },
            crate::PermissionRule {
                pattern: "edit:private/*".into(),
                decision: crate::PermissionDecision::Deny,
            },
        ]);
        engine.set_workspace(&workspace);
        let denied = |plan: &super::AskPlan| {
            plan.patterns.iter().any(|pattern| {
                engine.evaluate(&plan.operation(pattern)) == crate::PermissionDecision::Deny
            })
        };
        let list = super::ask_plans("list", &json!({"path":"alias"}), &workspace).remove(0);
        assert_eq!(list.patterns, vec!["alias", "build"]);
        assert!(denied(&list));
        let plain = super::ask_plans("list", &json!({"path":"src"}), &workspace).remove(0);
        assert_eq!(plain.patterns, vec!["src"]);
        assert!(!denied(&plain));
        let create = super::ask_plans(
            "workflow",
            &json!({"action":"create","name":"audit","source":"x"}),
            &workspace,
        );
        let edit = create
            .iter()
            .find(|plan| plan.permission == "edit")
            .unwrap();
        assert_eq!(
            edit.patterns,
            vec![".haarness/workflows/audit.ts", "private/flows/audit.ts"]
        );
        assert!(denied(edit));
        std::fs::remove_dir_all(workspace).unwrap();
    }

    #[test]
    fn a_patch_that_touches_a_configuration_file_anywhere_asks() {
        let workspace =
            std::env::temp_dir().join(format!("haarness-config-patch-{}", uuid::Uuid::now_v7()));
        std::fs::create_dir_all(&workspace).unwrap();
        let mut engine = crate::PermissionEngine::build_defaults();
        engine.set_workspace(&workspace);
        let protected = |body: &str| {
            let plans = super::ask_plans(
                "apply_patch",
                &json!({"input": format!("*** Begin Patch\n{body}*** End Patch")}),
                &workspace,
            );
            let edit = plans.iter().find(|plan| plan.permission == "edit").unwrap();
            edit.patterns
                .iter()
                .filter(|pattern| engine.evaluate_detailed(&edit.operation(pattern)).protected)
                .cloned()
                .collect::<Vec<_>>()
        };
        // A scratch file added and then moved onto haarness.json, a file
        // moved away from .mcp.json, and a config file deleted.
        assert_eq!(
            protected(
                "*** Add File: tmp/c.json\n+{}\n*** Update File: tmp/c.json\n*** Move to: haarness.json\n@@\n {}\n+\n"
            ),
            vec!["haarness.json"]
        );
        assert_eq!(
            protected("*** Update File: .mcp.json\n*** Move to: notes/mcp.txt\n@@\n {}\n+\n"),
            vec![".mcp.json"]
        );
        assert_eq!(
            protected("*** Delete File: .haarness/config.toml\n"),
            vec![".haarness/config.toml"]
        );
        assert!(protected("*** Add File: notes.md\n+x\n").is_empty());
        std::fs::remove_dir_all(workspace).unwrap();
    }

    #[test]
    fn a_patch_meets_the_rules_for_every_file_it_touches_and_moves_to() {
        let workspace =
            std::env::temp_dir().join(format!("haarness-patch-paths-{}", uuid::Uuid::now_v7()));
        std::fs::create_dir_all(workspace.join("src")).unwrap();
        std::fs::create_dir_all(workspace.join("vendor")).unwrap();
        std::fs::write(workspace.join("src/old.rs"), "a\n").unwrap();
        let patch = "*** Begin Patch\n\
            *** Update File: src/old.rs\n\
            *** Move to: vendor/lib.rs\n\
            @@\n-a\n+b\n\
            *** Add File: src/../vendor/new.rs\n+c\n\
            *** End Patch";
        let plan = super::ask_plans("apply_patch", &json!({"input": patch}), &workspace).remove(0);
        assert_eq!(plan.permission, "edit");
        assert_eq!(
            plan.patterns,
            vec![
                "src/old.rs",
                "vendor/lib.rs",
                "src/../vendor/new.rs",
                "vendor/new.rs"
            ]
        );
        assert_eq!(
            plan.resolved,
            vec![("vendor/new.rs".to_owned(), "vendor/new.rs".to_owned())]
        );
        let mut engine = crate::PermissionEngine::build_defaults();
        engine.set_workspace(&workspace);
        engine.add_rule(crate::PermissionRule {
            pattern: "edit:vendor/*".into(),
            decision: crate::PermissionDecision::Deny,
        });
        let denied: Vec<_> = plan
            .patterns
            .iter()
            .filter(|pattern| {
                engine.evaluate(&plan.operation(pattern)) == crate::PermissionDecision::Deny
            })
            .collect();
        assert_eq!(
            denied,
            vec!["vendor/lib.rs", "src/../vendor/new.rs", "vendor/new.rs"]
        );
        std::fs::remove_dir_all(workspace).unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn a_patch_that_deletes_or_moves_a_link_is_judged_by_the_link_itself() {
        let root =
            std::env::temp_dir().join(format!("haarness-patch-entry-{}", uuid::Uuid::now_v7()));
        let workspace = root.join("workspace");
        let outside = root.join("outside");
        std::fs::create_dir_all(&workspace).unwrap();
        std::fs::create_dir_all(&outside).unwrap();
        std::fs::write(outside.join("kept.txt"), "x\n").unwrap();
        std::fs::write(workspace.join(".env"), "SECRET=1\n").unwrap();
        std::os::unix::fs::symlink(outside.join("kept.txt"), workspace.join("out.txt")).unwrap();
        std::os::unix::fs::symlink(".env", workspace.join("notes.txt")).unwrap();
        let plans = |body: &str| {
            super::ask_plans(
                "apply_patch",
                &json!({"input": format!("*** Begin Patch\n{body}*** End Patch")}),
                &workspace,
            )
        };
        // Deleting a link inside the project removes only the link: nothing
        // outside is asked about, and the file it leads to is not named.
        let delete = plans("*** Delete File: out.txt\n*** Delete File: notes.txt\n");
        assert_eq!(
            delete.len(),
            1,
            "{:?}",
            delete
                .iter()
                .map(|plan| &plan.permission)
                .collect::<Vec<_>>()
        );
        assert_eq!(delete[0].patterns, vec!["out.txt", "notes.txt"]);
        // A move still reads through the link, so the folder it leads to is
        // asked about and its target meets the rules, as before.
        let moved = plans("*** Update File: out.txt\n*** Move to: copy.txt\n@@\n-x\n+y\n");
        let outside_folder = crate::paths::canonicalize(&outside).unwrap();
        assert_eq!(moved[0].permission, "external_directory");
        assert_eq!(
            moved[0].external_paths,
            vec![outside_folder.join("kept.txt")]
        );
        let moved =
            plans("*** Update File: notes.txt\n*** Move to: copy.txt\n@@\n-SECRET=1\n+SECRET=2\n");
        assert_eq!(moved[0].patterns, vec!["notes.txt", ".env", "copy.txt"]);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn webfetch_permissions_also_meet_the_rules_for_the_address_really_read() {
        let engine = crate::PermissionEngine::new(vec![crate::PermissionRule {
            pattern: "webfetch:https://denied.example/*".into(),
            decision: crate::PermissionDecision::Deny,
        }]);
        let plan = |url: &str| {
            let plan = super::ask_plans(
                "webfetch",
                &json!({"url": url}),
                std::path::Path::new("/workspace"),
            )
            .remove(0);
            assert_eq!(plan.permission, "webfetch");
            assert_eq!(plan.always, vec!["*"]);
            let denied = plan.patterns.iter().any(|pattern| {
                engine.evaluate(&plan.operation(pattern)) == crate::PermissionDecision::Deny
            });
            (plan.patterns, denied)
        };
        // An address written plainly is checked once, as written.
        for url in ["https://docs.example/guide", "https://docs.example/"] {
            assert_eq!(plan(url), (vec![url.to_owned()], false), "{url}");
        }
        // One with no path also as the page it reads, `/`, so a rule for
        // every page of the host holds for it, with or without a fragment.
        assert_eq!(
            plan("https://docs.example").0,
            vec!["https://docs.example", "https://docs.example/"]
        );
        for url in ["https://denied.example", "https://denied.example#part"] {
            assert!(plan(url).1, "{url}");
        }
        assert_eq!(
            plan("https://denied.example/secret"),
            (vec!["https://denied.example/secret".to_owned()], true)
        );
        // Other spellings of the same address meet the rule too.
        for url in [
            "HTTPS://DENIED.EXAMPLE/secret",
            "https://someone:password@denied.example/secret",
            "https://denied.example./secret",
            "https://denied.example:443/secret",
            "https://denied.example/public/../secret",
        ] {
            let (patterns, denied) = plan(url);
            assert!(denied, "{url}");
            assert_eq!(
                patterns,
                vec![url.to_owned(), "https://denied.example/secret".to_owned()]
            );
        }
        // So do the address without its fragment, and its path with the
        // letters a `%` code spells written plainly.
        for (url, read) in [
            (
                "https://denied.example/secret#part",
                "https://denied.example/secret",
            ),
            (
                "https://denied.example/%73ecret",
                "https://denied.example/secret",
            ),
            (
                "https://Denied.Example/%73%45cret%7e#x",
                "https://denied.example/sEcret~",
            ),
        ] {
            let (patterns, _) = plan(url);
            assert_eq!(patterns, vec![url.to_owned(), read.to_owned()], "{url}");
        }
        assert!(plan("https://denied.example/%73ecret").1);
        assert!(plan("https://denied.example/secret#part").1);
        // The `/` written before a fragment stays.
        assert_eq!(
            plan("https://docs.example/#top").0,
            vec!["https://docs.example/#top", "https://docs.example/"]
        );
        assert_eq!(
            plan("https://docs.example#top").0,
            vec![
                "https://docs.example#top",
                "https://docs.example",
                "https://docs.example/"
            ]
        );
        // A host in punycode also meets a rule that names it in Unicode.
        let books = crate::PermissionEngine::new(vec![crate::PermissionRule {
            pattern: "webfetch:https://bücher.example/*".into(),
            decision: crate::PermissionDecision::Deny,
        }]);
        let (patterns, _) = plan("https://xn--bcher-kva.example/list");
        assert_eq!(
            patterns,
            vec![
                "https://xn--bcher-kva.example/list",
                "https://bücher.example/list"
            ]
        );
        assert!(patterns.iter().any(|pattern| {
            books.evaluate(&format!("webfetch:{pattern}")) == crate::PermissionDecision::Deny
        }));
        // Other codes stay as written: `%2F` is not a folder's `/`.
        assert_eq!(
            plan("https://docs.example/a%2Fb%20c%zz%4"),
            (
                vec!["https://docs.example/a%2Fb%20c%zz%4".to_owned()],
                false
            )
        );
        // Another port is another address.
        assert!(!plan("https://denied.example:8443/secret").1);
    }

    #[test]
    fn an_address_without_a_scheme_is_read_and_judged_as_the_fetch_reads_it() {
        for (written, read) in [
            ("docs.rs/serde", "https://docs.rs/serde"),
            ("  www.python.org/doc/ ", "https://www.python.org/doc/"),
            ("//example.com/x?y#z", "https://example.com/x?y#z"),
            ("example.com:8443/x", "https://example.com:8443/x"),
            ("bücher.example/list", "https://bücher.example/list"),
            (
                "docs.rs/releases/search?query=https://x",
                "https://docs.rs/releases/search?query=https://x",
            ),
            ("docs.rs.", "https://docs.rs."),
            ("localhost:3000/api", "http://localhost:3000/api"),
            ("LOCALHOST", "http://LOCALHOST"),
            ("app.localhost:5173", "http://app.localhost:5173"),
            ("printer.local/status", "http://printer.local/status"),
            ("127.0.0.1:8080/health", "http://127.0.0.1:8080/health"),
            ("192.168.1.10/admin", "http://192.168.1.10/admin"),
            ("10.0.0.2:9000", "http://10.0.0.2:9000"),
            (
                "169.254.169.254/latest/meta-data",
                "http://169.254.169.254/latest/meta-data",
            ),
            ("[::1]:8080/x", "http://[::1]:8080/x"),
            ("[fd00::1]/x", "http://[fd00::1]/x"),
            ("8.8.8.8/dns", "https://8.8.8.8/dns"),
            // Written with a scheme, or not an address at all: as written.
            ("https://example.com/a", "https://example.com/a"),
            ("ftp://example.com/a", "ftp://example.com/a"),
            ("file:///etc/passwd", "file:///etc/passwd"),
            ("mailto:someone@example.com", "mailto:someone@example.com"),
            ("javascript:alert(1)", "javascript:alert(1)"),
            ("data:text/html,hi", "data:text/html,hi"),
            ("someone@example.com/x", "someone@example.com/x"),
            ("src/main.rs", "src/main.rs"),
            ("example", "example"),
            ("example.com:/x", "example.com:/x"),
            ("example.com:http/x", "example.com:http/x"),
            ("[not-an-ip]/x", "[not-an-ip]/x"),
            ("", ""),
        ] {
            assert_eq!(super::webfetch_address(written), read, "{written:?}");
        }
        // A rule for the address read holds for the address as written, so
        // leaving out the scheme cannot step around it.
        let engine = crate::PermissionEngine::new(vec![
            crate::PermissionRule {
                pattern: "webfetch:https://denied.example/*".into(),
                decision: crate::PermissionDecision::Deny,
            },
            crate::PermissionRule {
                pattern: "webfetch:http://localhost:3000/*".into(),
                decision: crate::PermissionDecision::Deny,
            },
            crate::PermissionRule {
                pattern: "webfetch:http://169.254.169.254/*".into(),
                decision: crate::PermissionDecision::Deny,
            },
        ]);
        for (written, denied) in [
            ("denied.example/secret", true),
            ("DENIED.example./secret", true),
            ("//denied.example/secret", true),
            ("localhost:3000/admin", true),
            ("169.254.169.254/latest/meta-data", true),
            ("allowed.example/page", false),
            ("localhost:3001/admin", false),
        ] {
            let plan = super::ask_plans(
                "webfetch",
                &json!({"url": written}),
                std::path::Path::new("/workspace"),
            )
            .remove(0);
            assert_eq!(
                plan.patterns.iter().any(|pattern| {
                    engine.evaluate(&plan.operation(pattern)) == crate::PermissionDecision::Deny
                }),
                denied,
                "{written}: {:?}",
                plan.patterns
            );
        }
        assert_eq!(
            super::webfetch_redirect_verdict(
                &engine,
                "denied.example/start",
                "https://denied.example/next"
            ),
            crate::PermissionDecision::Deny
        );
    }

    #[test]
    fn a_redirect_on_the_address_asked_for_is_followed_only_where_its_approval_reaches() {
        use crate::PermissionDecision::{Allow, Ask, Deny};
        let rule = |pattern: &str, decision| crate::PermissionRule {
            pattern: pattern.into(),
            decision,
        };
        let engine = |rules: &[(&str, crate::PermissionDecision)]| {
            let mut engine = crate::PermissionEngine::build_defaults();
            for (pattern, decision) in rules {
                engine.add_rule(rule(pattern, *decision));
            }
            engine
        };
        let verdict = |engine: &crate::PermissionEngine, asked: &str, hop: &str| {
            super::webfetch_redirect_verdict(engine, asked, hop)
        };
        let login = "https://intra.example/login?next=/admin/x";
        // Under the defaults every hop is followed, as before.
        let defaults = crate::PermissionEngine::build_defaults();
        assert_eq!(
            verdict(&defaults, login, "https://intra.example/admin/x"),
            Allow
        );
        // A path a rule denies is not reached through a redirect, in any
        // spelling of it.
        let denied = engine(&[("webfetch:https://intra.example/admin/*", Deny)]);
        for hop in [
            "https://intra.example/admin/x",
            "https://someone@intra.example/admin/x",
            "https://intra.example./admin/x",
            "https://intra.example/public/../admin/x",
            "https://intra.example/%61dmin/x",
            "https://intra.example/admin/x#top",
        ] {
            assert_eq!(verdict(&denied, login, hop), Deny, "{hop}");
        }
        // A skill's `disallowed-tools` holds on a redirect too, and a rule
        // that names a host in Unicode holds for the punycode a redirect
        // arrives in.
        let skill = haarness_protocol::DefinitionExecution {
            disallowed_tools: vec!["WebFetch(https://intra.example/admin/*)".into()],
            ..haarness_protocol::DefinitionExecution::default()
        };
        let skilled = super::with_skill_rules(
            crate::PermissionEngine::build_defaults(),
            crate::definitions::skill_rules(&skill, "/workspace"),
        );
        assert_eq!(
            verdict(&skilled, login, "https://intra.example/admin/x"),
            Deny
        );
        assert_eq!(
            verdict(&skilled, login, "https://intra.example/home"),
            Allow
        );
        let books = engine(&[("webfetch:https://bücher.example/private/*", Deny)]);
        for hop in [
            "https://xn--bcher-kva.example/private/x",
            "https://bücher.example/private/x",
        ] {
            assert_eq!(
                verdict(&books, "https://xn--bcher-kva.example/", hop),
                Deny,
                "{hop}"
            );
        }
        assert_eq!(verdict(&denied, login, "https://intra.example/home"), Allow);
        // `"webfetch": "ask"`: the call's approval was for the tool, and the
        // hop asks the same question.
        let ask_all = engine(&[("webfetch:*", Ask)]);
        assert_eq!(
            verdict(&ask_all, login, "https://intra.example/home"),
            Allow
        );
        // A rule that asks about a path still asks after a redirect, whether
        // the call itself was allowed or asked about for the whole tool.
        let ask_admin = engine(&[("webfetch:https://intra.example/admin/*", Ask)]);
        assert_eq!(
            verdict(&ask_admin, login, "https://intra.example/admin/x"),
            Ask
        );
        let ask_both = engine(&[
            ("webfetch:*", Ask),
            ("webfetch:https://intra.example/admin/*", Ask),
        ]);
        assert_eq!(
            verdict(&ask_both, login, "https://intra.example/admin/x"),
            Ask
        );
        // An approval of one address under a rule about a host never opens
        // another page of it.
        let ask_host = engine(&[("webfetch:https://intra.example/*", Ask)]);
        assert_eq!(verdict(&ask_host, login, "https://intra.example/home"), Ask);
        // An allow, or an Always, for one path covers that path only.
        let mut docs = engine(&[
            ("webfetch:*", Ask),
            ("webfetch:https://intra.example/docs/*", Allow),
        ]);
        let start = "https://intra.example/docs/start";
        assert_eq!(
            verdict(&docs, start, "https://intra.example/docs/moved"),
            Allow
        );
        assert_eq!(verdict(&docs, start, "https://intra.example/private"), Ask);
        let mut always = engine(&[("webfetch:*", Ask)]);
        always.add_grant(rule("webfetch:https://intra.example/docs/*", Allow));
        assert_eq!(
            verdict(&always, start, "https://intra.example/private"),
            Ask
        );
        // An Always for the whole tool opens what is not denied.
        docs.add_grant(rule("webfetch:*", Allow));
        docs.add_rule(rule("webfetch:https://intra.example/admin/*", Deny));
        assert_eq!(
            verdict(&docs, start, "https://intra.example/private"),
            Allow
        );
        assert_eq!(verdict(&docs, start, "https://intra.example/admin/x"), Deny);
    }

    #[test]
    fn pending_questions_keep_child_scope_and_publish_resolution() {
        let root = ThreadId::new();
        let first_child = ThreadId::new();
        let second_child = ThreadId::new();
        let first_turn = TurnId::new();
        let second_turn = TurnId::new();
        let (first_sender, _first_receiver) = oneshot::channel();
        let (second_sender, _second_receiver) = oneshot::channel();
        let first = PendingQuestion {
            prompt: "First?".into(),
            choices: vec!["yes".into(), "no".into()],
            multiple: false,
            custom: false,
            thread_id: first_child,
            root_thread_id: root,
            turn_id: first_turn,
            call_id: "call-question".into(),
            created_at: Utc::now(),
            sender: first_sender,
        };
        let second = PendingQuestion {
            prompt: "Second?".into(),
            choices: vec![],
            multiple: false,
            custom: false,
            thread_id: second_child,
            root_thread_id: root,
            turn_id: second_turn,
            call_id: "call-question".into(),
            created_at: Utc::now(),
            sender: second_sender,
        };

        let first_info = first.info("question-1");
        let second_info = second.info("question-2");
        assert_eq!(first_info.root_thread_id, Some(root));
        assert_eq!(first_info.thread_id, first_child);
        assert_eq!(first_info.turn_id, Some(first_turn));
        assert_eq!(second_info.thread_id, second_child);
        assert_ne!(first_info.question_id, second_info.question_id);

        let events = EventBus::new(8);
        first.publish_resolved(&events, "question-1", "answered");
        let resolved = events
            .subscribe(None)
            .replay
            .into_iter()
            .find(|event| event.event_type == "question.resolved")
            .expect("resolution event");
        assert_eq!(resolved.thread_id, Some(first_child));
        assert_eq!(resolved.root_thread_id, Some(root));
        assert_eq!(resolved.turn_id, Some(first_turn));
        assert_eq!(resolved.payload["questionId"], "question-1");
        assert_eq!(resolved.payload["resolution"], "answered");
    }

    #[test]
    fn a_broken_connection_is_a_cut_but_an_error_the_provider_sent_is_not() {
        let provider = |message: &str| CoreError::Provider(message.into());
        for cut in [
            // reqwest's words for a body read that failed, with its cause.
            "request or response body error: connection reset by peer (os error 54)",
            "request or response body error: error reading a body from connection: stream error received: unexpected internal error encountered",
            "error decoding response body: connection closed before message completed",
            "request or response body error: unexpected EOF during chunk size line",
            // A Haarness router whose upstream fell silent, or broke off.
            "upstream stream became idle",
            "upstream stream failed: error decoding response body",
            "the provider sent nothing for 5 minutes",
        ] {
            assert!(super::is_stream_cut(&provider(cut)), "{cut}");
        }
        for failed in [
            r#"{"type":"error","error":{"type":"overloaded_error","message":"Overloaded"}}"#,
            r#"{"type":"response.failed","response":{"error":{"code":"server_error","message":"The connection reset while processing."}}}"#,
            "invalid SSE JSON: EOF while parsing an object at line 1 column 12",
            "HTTP 400 Bad Request: invalid tool schema",
            "provider returned a tool call without a call ID or name",
        ] {
            assert!(!super::is_stream_cut(&provider(failed)), "{failed}");
        }
        assert!(!super::is_stream_cut(&CoreError::ProviderIncomplete(
            "connection reset".into()
        )));
        assert!(!super::is_stream_cut(&CoreError::Cancelled));
    }

    #[test]
    fn busy_or_unreachable_providers_are_retried_but_limits_and_bad_requests_are_not() {
        let provider = |message: &str| CoreError::Provider(message.into());
        for retried in [
            "HTTP 503 Service Unavailable: This model is currently experiencing high demand.",
            "HTTP 529: overloaded_error",
            "HTTP 502 Bad Gateway",
            "error sending request for url (https://api.example/v1/messages)",
            // A connection that broke while the response began, wrapped as
            // reqwest's body error whatever broke it (a reset, Windows'
            // 10054, an HTTP/2 stream error), or a router's silent upstream.
            "request or response body error: connection reset by peer (os error 54)",
            "request or response body error: An existing connection was forcibly closed by the remote host. (os error 10054)",
            "request or response body error: error reading a body from connection: stream error received: unexpected internal error encountered",
            "error decoding response body: unexpected EOF during chunk size line",
            "upstream stream became idle",
            // A tunnel or proxy before a server set up here.
            "HTTP 524: A timeout occurred",
            "HTTP 520 <unknown status code>: Web server is returning an unknown error",
            "HTTP 508 Loop Detected",
            // OpenAI's Responses stream: a response its server failed, or was
            // too busy, to finish, after a 200.
            r#"{"type":"response.failed","response":{"status":"failed","error":{"code":"server_error","message":"An error occurred while processing your request. You can retry your request, or contact us through our help center at help.openai.com if the error persists. Please include the request ID req_0123 in your message."}}}"#,
            r#"{"type":"error","code":"server_is_overloaded","message":"Our servers are currently overloaded. Please try again later.","param":null,"sequence_number":2}"#,
            r#"{"type":"response.failed","response":{"error":{"code":"slow_down","message":"Please slow down."}}}"#,
            r#"{"type":"error","error":{"type":"api_error","message":"Internal server error"}}"#,
        ] {
            assert!(
                super::is_provider_transient(&provider(retried)),
                "{retried}"
            );
        }
        // What the request asked for, refused: another try is refused too.
        for refused in [
            r#"{"type":"response.failed","response":{"error":{"code":"invalid_prompt","message":"Invalid prompt: your prompt was flagged as potentially violating our usage policy."}}}"#,
            r#"{"type":"response.failed","response":{"error":{"code":"context_length_exceeded","message":"Your input exceeds the context window of this model."}}}"#,
        ] {
            assert!(
                !super::is_provider_transient(&provider(refused)),
                "{refused}"
            );
        }
        for failed in [
            "HTTP 429: rate limit exceeded",
            "HTTP 400 Bad Request: API key not valid",
            "HTTP 413 Payload Too Large: maximum context length exceeded",
            "HTTP 501 Not Implemented",
        ] {
            assert!(!super::is_provider_transient(&provider(failed)), "{failed}");
        }
        assert!(!super::is_provider_transient(&CoreError::Cancelled));
        // A per-minute limit that names a short wait is sat out; a daily
        // quota or an unnamed wait fails the turn with its message.
        let per_minute = provider(
            "HTTP 429 Too Many Requests: You exceeded your current quota. \
             * Quota exceeded for metric: generate_content_free_tier_requests, limit: 5\n\
             Please retry in 17.197029539s.",
        );
        let wait = super::retry_delay(&per_minute, 1).unwrap();
        assert!((18..=19).contains(&wait.as_secs()), "{wait:?}");
        assert!(super::retry_delay(&provider("HTTP 429: rate limit exceeded"), 1).is_none());
        // OpenRouter's answer when a model's shared upstream pool is full.
        let shared = provider(
            "HTTP 429 Too Many Requests: Alibaba: qwen/qwen3.8-flash is temporarily \
             rate-limited upstream. Please retry shortly, or add your own key to accumulate \
             your rate limits: https://openrouter.ai/settings/integrations",
        );
        assert_eq!(
            super::retry_delay(&shared, 1),
            Some(std::time::Duration::from_secs(2))
        );
        assert_eq!(
            super::retry_delay(&shared, 3),
            Some(std::time::Duration::from_secs(8))
        );
        // Vertex's answer when its shared capacity is busy.
        let vertex_busy = provider(
            "HTTP 429 Too Many Requests: Resource exhausted. Please try again later. \
             Please refer to https://cloud.google.com/vertex-ai/generative-ai/docs/error-code-429 \
             for more details.",
        );
        assert_eq!(
            super::retry_delay(&vertex_busy, 2),
            Some(std::time::Duration::from_secs(4))
        );
        assert!(
            super::retry_delay(
                &provider("HTTP 429: quota exceeded. Please retry in 7200s."),
                1
            )
            .is_none()
        );
        // A named wait up to 90 seconds is sat out, a second more; a longer
        // one fails.
        for (named, waited) in [
            ("89.5s", Some(90_500)),
            ("90s", Some(91_000)),
            ("90.5s", None),
        ] {
            assert_eq!(
                super::retry_delay(
                    &provider(&format!(
                        "HTTP 429: rate limit exceeded. Please retry in {named}."
                    )),
                    1
                ),
                waited.map(std::time::Duration::from_millis),
                "{named}"
            );
        }
        // A daily quota names hours: never mistaken for seconds.
        assert!(
            super::retry_delay(
                &provider("HTTP 429: limit: 20. Please retry in 21h16m10.222s."),
                1
            )
            .is_none()
        );
        assert_eq!(
            super::advised_wait("1m30s."),
            Some(std::time::Duration::from_secs(90))
        );
        assert_eq!(
            super::advised_wait("500ms"),
            Some(std::time::Duration::from_millis(500))
        );
        assert_eq!(super::advised_wait("soon"), None);
        assert_eq!(
            super::retry_delay(&provider("HTTP 503 Service Unavailable"), 3),
            Some(std::time::Duration::from_secs(8))
        );
    }

    /// A Haarness router holds requests to a provider that failed several in
    /// a row, and names the hold: the retry waits it out instead of being
    /// refused again at 2, 4, 8 and 16 seconds, and the person reads the
    /// router's words without a status line or code.
    #[test]
    fn a_router_hold_is_waited_out_and_read_plainly() {
        let provider = |message: &str| CoreError::Provider(message.into());
        let own_router = |wait: &str| {
            provider(&format!(
                "HTTP 503 Service Unavailable: [no_route_available] This model's provider failed \
                 several requests in a row, so the router is holding requests to it for a moment. \
                 Try again in {wait}, or choose another model."
            ))
        };
        // Haarness Cloud's words for the same hold.
        let cloud = provider(
            "This model's provider is temporarily unavailable: it failed several requests in a \
             row, so Haarness Cloud is holding requests to it for a moment. Please retry in 28s, \
             or choose another model.",
        );
        for error in [own_router("28 seconds"), cloud.clone()] {
            assert!(super::is_provider_transient(&error), "{error}");
            assert_eq!(
                super::retry_delay(&error, 1),
                Some(std::time::Duration::from_secs(29)),
                "{error}"
            );
            let words = super::describe_error(&error, Some("Haarness Cloud"));
            assert!(words.starts_with("This model's provider "), "{words}");
            assert!(!words.contains("HTTP") && !words.contains('['), "{words}");
        }
        // A hold shorter than the backoff keeps the backoff; one longer than
        // a turn waits fails now, with its words.
        assert_eq!(
            super::retry_delay(&own_router("1 seconds"), 3),
            Some(std::time::Duration::from_secs(8))
        );
        assert_eq!(super::retry_delay(&own_router("120 seconds"), 1), None);
        // Words that are not a sentence get advice of their own.
        assert_eq!(
            super::describe_error(
                &provider(
                    "HTTP 503 Service Unavailable: [no_route_available] all configured routes are unavailable"
                ),
                Some("My router")
            ),
            "My router can't reach this model's provider right now. Try again in a moment, or choose another model."
        );
        // A router's per-minute refusal that names its wait is sat out too.
        assert_eq!(
            super::retry_delay(
                &provider(
                    "HTTP 429 Too Many Requests: [upstream_429] The provider is rate limiting the \
                     router's key. Try again in 12 seconds."
                ),
                1
            ),
            Some(std::time::Duration::from_secs(13))
        );
        assert_eq!(super::named_wait("try again in a moment"), None);
        assert_eq!(
            super::named_wait("try again in 2 minutes."),
            Some(std::time::Duration::from_secs(120))
        );
    }

    /// OpenAI's and Groq's per-minute limits name their wait as a duration
    /// ("Please try again in 1.054s"): the turn sits it out instead of
    /// failing at once.
    #[test]
    fn a_per_minute_limit_named_as_a_duration_is_waited_out() {
        let provider = |raw: &str| CoreError::Provider(raw.into());
        let openai = provider(
            "HTTP 429 Too Many Requests: [rate_limit_exceeded] Rate limit reached for gpt-6-luna in \
             organization org-test on tokens per min (TPM): Limit 30000, Used 29000, Requested 4600. \
             Please try again in 1.054s. Visit https://platform.openai.com/account/rate-limits to learn more.",
        );
        let wait = super::retry_delay(&openai, 1).unwrap();
        assert!((2000..2100).contains(&wait.as_millis()), "{wait:?}");
        // The same limit as a stream's failed response event.
        let event = provider(
            r#"{"type":"response.failed","response":{"error":{"code":"rate_limit_exceeded","message":"Rate limit reached for gpt-6-luna on tokens per min (TPM). Please try again in 11.054s."}}}"#,
        );
        assert_eq!(
            super::retry_delay(&event, 1).map(|wait| wait.as_secs()),
            Some(12)
        );
        for (words, seconds) in [
            ("try again in 1m3.2s.", 63.2),
            ("try again in 260ms.", 0.26),
            ("try again in 20.5 seconds.", 20.5),
            ("try again in 2 minutes.", 120.0),
        ] {
            let wait = super::named_wait(words).unwrap();
            assert!(
                (wait.as_secs_f64() - seconds).abs() < 1e-6,
                "{words}: {wait:?}"
            );
        }
        // A wait longer than a turn sits out fails now, and one too long to
        // hold is no wait, not a panic.
        assert_eq!(
            super::retry_delay(
                &provider(
                    "HTTP 429 Too Many Requests: Rate limit reached. Please try again in 6m0s."
                ),
                1
            ),
            None
        );
        assert_eq!(
            super::named_wait("please retry in 999999999999999999999999999999s"),
            None
        );
        assert_eq!(
            super::named_wait("try again in 999999999999999999999999999999 seconds"),
            None
        );
        // A request larger than the whole per-minute allowance waits for
        // nothing, and says so in OpenAI's words for it.
        let too_large = provider(
            "HTTP 429 Too Many Requests: [rate_limit_exceeded] Request too large for gpt-6-luna in \
             organization org-test on tokens per min (TPM): Limit 30000, Requested 45000. The input or \
             output tokens must be reduced in order to run successfully. Visit \
             https://platform.openai.com/account/rate-limits to learn more.",
        );
        assert_eq!(super::retry_delay(&too_large, 1), None);
        assert_eq!(
            super::describe_error(&too_large, Some("OpenAI")),
            "OpenAI allows this account 30,000 tokens a minute, and this request needs 45,000, so it can't be sent. Upgrade the plan at https://platform.openai.com/account/rate-limits, or choose another model or provider."
        );
    }

    /// A sign-in server that is busy or down while renewing has spent no
    /// refresh token: the turn tries again, and says so plainly if it can't.
    #[test]
    fn a_busy_sign_in_server_is_retried_and_said_plainly() {
        for raw in [
            "OpenAI sign-in failed: refresh token returned 503 Service Unavailable",
            "OpenAI sign-in failed: refresh token returned 429 Too Many Requests",
        ] {
            let error = CoreError::Provider(raw.into());
            assert!(super::is_provider_transient(&error), "{raw}");
            assert!(super::retry_delay(&error, 1).is_some(), "{raw}");
            assert_eq!(
                super::describe_error(&error, Some("OpenAI")),
                "OpenAI couldn't renew your sign-in just now: its sign-in service is busy or down. Send your message again in a moment."
            );
        }
        // A refused renewal still asks for a new sign-in, at once.
        let spent = CoreError::Provider(
            "OpenAI sign-in failed: refresh token returned 401 Unauthorized".into(),
        );
        assert!(!super::is_provider_transient(&spent));
        assert_eq!(super::retry_delay(&spent, 1), None);
        assert_eq!(
            super::describe_error(&spent, Some("OpenAI")),
            "Your OpenAI sign-in has expired or was ended elsewhere. Connect OpenAI again to sign in."
        );
    }

    /// A ChatGPT sign-in runs only the models its plan includes: a model
    /// outside them is still offered with an API key, not retired. The plan's
    /// usage limit is no refused model.
    #[test]
    fn a_model_outside_a_chatgpt_plan_is_said_to_need_an_api_key() {
        let named = |id: &str, name: &str| ModelInfo {
            display_name: name.into(),
            ..model_info(id, 272_000)
        };
        let chatgpt = haarness_protocol::ProviderInfo {
            id: "openai".into(),
            name: "OpenAI".into(),
            authenticated: true,
            models: vec![
                named("gpt-6.1-sol", "GPT-6.1 Sol"),
                named("gpt-6-astra", "GPT-6 Astra"),
                named("gpt-6-luna", "GPT-6 Luna"),
            ],
        };
        for raw in [
            "HTTP 400 Bad Request: [model_not_found] The 'gpt-5.4-mini' model is not supported when using Codex with a ChatGPT account.",
            "OpenAI model gpt-5.4-mini is not available on this ChatGPT account. Available: gpt-6.1-sol, gpt-6-astra, gpt-6-luna. Choose one of those, or sign in with an OpenAI API key for the public Responses API.",
        ] {
            let error = CoreError::Provider(raw.into());
            assert_eq!(
                super::describe_model_refusal(&error, &chatgpt, "gpt-5.4-mini", true).as_deref(),
                Some(
                    "GPT-5.4 Mini isn't included with a ChatGPT sign-in. Choose another model for this chat, such as GPT-6.1 Sol, GPT-6 Astra or GPT-6 Luna, or connect OpenAI with an API key to use GPT-5.4 Mini."
                ),
                "{raw}"
            );
            assert_eq!(
                super::describe_model_refusal(&error, &chatgpt, "gpt-5.4-mini", false).as_deref(),
                Some("GPT-5.4 Mini isn't included with this ChatGPT sign-in.")
            );
        }
        let words = "Your ChatGPT Plus plan has reached its usage limit, which resets in about 3 hours. Every model on your ChatGPT sign-in counts toward it: wait for the reset, or choose a model from another provider for this chat.";
        let limited = CoreError::Provider(words.into());
        for model in ["gpt-6-luna", "gpt-9"] {
            assert_eq!(
                super::describe_model_refusal(&limited, &chatgpt, model, true),
                None
            );
        }
        assert!(super::is_provider_usage_limit(&limited));
        assert_eq!(super::retry_delay(&limited, 1), None);
        assert_eq!(super::describe_error(&limited, Some("OpenAI")), words);
        assert_eq!(
            super::stop_failure_categories(&limited),
            ("provider", "rate_limit")
        );
    }

    #[test]
    fn provider_usage_limit_classification_is_conservative() {
        assert!(super::is_provider_usage_limit(&CoreError::Provider(
            "HTTP 429: rate limit exceeded".into()
        )));
        assert!(super::is_provider_usage_limit(&CoreError::Provider(
            "insufficient_quota".into()
        )));
        assert!(!super::is_provider_usage_limit(&CoreError::Provider(
            "upstream connection reset".into()
        )));
        assert!(!super::is_provider_usage_limit(&CoreError::Tool(
            "rate limit".into()
        )));
    }

    #[test]
    fn long_titles_end_at_a_word_with_an_ellipsis() {
        assert_eq!(
            super::shorten_title("Echo: Hello! Can you explain what this project does?", 50),
            "Echo: Hello! Can you explain what this project…"
        );
        assert_eq!(
            super::shorten_title("Fix the login bug", 50),
            "Fix the login bug"
        );
        assert_eq!(
            super::shorten_title("Review the parser, the lexer and the formatter today", 30),
            "Review the parser, the lexer…"
        );
        let cjk = "解释这个项目做什么以及它是如何组织的请详细说明每个模块的职责和它们之间的关系";
        let short = super::shorten_title(cjk, 20);
        assert_eq!(short.chars().count(), 20);
        assert!(short.ends_with('…'));
    }

    #[test]
    fn provider_failures_are_clean_and_actionable_in_the_transcript() {
        assert!(
            super::user_facing_error(&CoreError::Provider(
                "HTTP 429: [exposure_cap] request reserve exceeded".into()
            ))
            .starts_with("Haarness Cloud's pending-request allowance")
        );
        let policy = CoreError::Provider(
            r#"{"type":"error","error":{"type":"invalid_request","code":"cyber_policy","message":"This content was flagged for possible cybersecurity risk."}}"#
                .into(),
        );
        assert_eq!(
            super::user_facing_error(&policy),
            "Provider rejected the request (cyber_policy): This content was flagged for possible cybersecurity risk."
        );
        assert_eq!(
            super::user_facing_error(&CoreError::Provider(
                "error sending request for url (https://api.example.test/v1)".into()
            )),
            "Could not reach the provider at api.example.test. Check the network connection and provider endpoint, then retry."
        );
        let refused = CoreError::Provider(
            "error sending request for url (http://127.0.0.1:9/v1/chat/completions): Connection refused (os error 61)"
                .into(),
        );
        assert_eq!(
            super::describe_error(&refused, Some("Local models")),
            "Could not reach Local models at 127.0.0.1:9 (connection refused). Check the network connection and provider endpoint, then retry."
        );
        // A refused local port is retried once (a server still starting),
        // not for half a minute; a remote one keeps its backoff.
        assert!(super::retry_delay(&refused, 1).is_some());
        assert!(super::retry_delay(&refused, 2).is_none());
        let remote = CoreError::Provider(
            "error sending request for url (https://api.example.test/v1): Connection refused"
                .into(),
        );
        assert!(super::retry_delay(&remote, 3).is_some());
        assert!(super::refused_on_this_machine(&CoreError::Provider(
            "error sending request for url (http://localhost:1234/v1): connection refused".into()
        )));
        assert!(super::refused_on_this_machine(&CoreError::Provider(
            "error sending request for url (http://[::1]:1234/v1): connection refused".into()
        )));
        assert_eq!(
            super::user_facing_error(&CoreError::Provider("HTTP 429: insufficient_quota".into())),
            "Provider rate limit or quota reached. Wait and retry, or check the account quota."
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    "HTTP 429 Too Many Requests: Request too large for model `openai/gpt-oss-120b` in organization `org_1` service tier `on_demand` on tokens per minute (TPM): Limit 8000, Requested 11419, please reduce your message size and try again. Need more tokens? Upgrade to Dev Tier today at https://console.groq.com/settings/billing".into()
                ),
                Some("Groq")
            ),
            "Groq allows this account 8,000 tokens a minute, and this request needs 11,419, so it can't be sent. Upgrade the plan at https://console.groq.com/settings/billing, or choose another model or provider."
        );
        // Groq's output allowance is of the reply it expects, not the request.
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    "HTTP 429 Too Many Requests: Request too large for model `qwen/qwen3.8-27b` in organization `org_1` service tier `on_demand` on output tokens per minute (OTPM): Limit 1000, Requested 1404. The request's expected output tokens exceed the enforced limit; reduce max_tokens (or the request's expected output) and try again. Need more tokens? Upgrade to Dev Tier today at https://console.groq.com/settings/billing".into()
                ),
                Some("Groq")
            ),
            "Groq allows this account 1,000 reply tokens a minute on this model, fewer than a reply here needs, so it can't be sent. Upgrade the plan at https://console.groq.com/settings/billing, or choose another model."
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider("HTTP 402 Payment Required: Insufficient Balance".into()),
                Some("DeepSeek")
            ),
            "Your DeepSeek account is out of credit (Insufficient Balance). Add credit with DeepSeek, then try again."
        );
        // A Haarness router says whose account ran out of credit, and a turn
        // does not wait for an account that only a top-up brings back.
        for (raw, words) in [
            (
                "HTTP 503 Service Unavailable: [provider_out_of_credit] This router's account with \
                 the provider has run out of credit, so this model can't answer until the account is \
                 topped up. Choose a model from another provider meanwhile.",
                "This router's account with the provider has run out of credit, so this model can't \
                 answer until the account is topped up. Choose a model from another provider meanwhile.",
            ),
            (
                "HTTP 402 Payment Required: [provider_out_of_credit] The provider account behind this \
                 key has run out of credit, so the provider refused the request. Add credit with the \
                 provider, or use another key or provider.",
                "The provider account behind this key has run out of credit, so the provider refused \
                 the request. Add credit with the provider, or use another key or provider.",
            ),
        ] {
            let refused = CoreError::Provider(raw.into());
            assert_eq!(
                super::describe_error(&refused, Some("Haarness Router")),
                words
            );
            assert!(!super::is_provider_transient(&refused), "{raw}");
            assert_eq!(super::retry_delay(&refused, 1), None, "{raw}");
        }
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    "HTTP 429 Too Many Requests: Alibaba: qwen/qwen3.8-flash is temporarily \
                     rate-limited upstream. Please retry shortly."
                        .into()
                ),
                Some("OpenRouter")
            ),
            "OpenRouter rate limit or quota reached: Alibaba: qwen/qwen3.8-flash is temporarily rate-limited upstream. Please retry shortly."
        );
        // The managed router's own words for an upstream limit.
        let routed = CoreError::Provider(
            "The provider is rate limiting this model right now. Try again in a moment, or choose another model.".into(),
        );
        assert_eq!(
            super::describe_error(&routed, Some("Haarness Cloud")),
            "The provider is rate limiting this model right now. Try again in a moment, or choose another model."
        );
        assert_eq!(
            super::retry_delay(&routed, 2),
            Some(std::time::Duration::from_secs(4))
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider("HTTP 401 Unauthorized: invalid x-api-key".into()),
                Some("Anthropic")
            ),
            "Anthropic rejected the API key or sign-in (invalid x-api-key). Connect Anthropic again to replace it."
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    "HTTP 401 Unauthorized: [invalid_api_key] Incorrect API key provided.".into()
                ),
                Some("OpenAI")
            ),
            "OpenAI rejected the API key or sign-in (Incorrect API key provided). Connect OpenAI again to replace it."
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    r#"HTTP 401 Unauthorized: {"error":{"type":"authentication_error","message":"Invalid bearer token."}}"#.into()
                ),
                Some("Amazon Bedrock")
            ),
            "Amazon Bedrock rejected the API key or sign-in (Invalid bearer token). Connect Amazon Bedrock again to replace it."
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    r#"HTTP 401 Unauthorized: {"error":{"code":401,"message":"API keys are not supported by this API. Expected OAuth2 access token or other authentication credentials that assert a principal.","status":"UNAUTHENTICATED"}}"#.into()
                ),
                Some("Google Vertex AI")
            ),
            "Google Vertex AI did not accept this API key. It takes a key bound to a service account; a key from Google AI Studio connects as Gemini instead."
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    "HTTP 403 Forbidden: unauthorized: not licensed to use Copilot".into()
                ),
                Some("GitHub Copilot")
            ),
            "This GitHub account has no Copilot plan. Turn on Copilot at github.com/settings/copilot, then try again."
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    r#"HTTP 400 Bad Request: {"error":{"message":"The requested model is not supported.","code":"model_not_supported","param":"model","type":"invalid_request_error"}}"#.into()
                ),
                Some("GitHub Copilot")
            ),
            "Your GitHub Copilot plan doesn't include this model. Choose another model, or turn it on at github.com/settings/copilot."
        );
        assert_eq!(
            super::user_facing_error(&CoreError::Provider("HTTP 401 Unauthorized".into())),
            "The provider rejected the API key or sign-in. Connect it again to replace it."
        );
        assert_eq!(
            super::describe_error(
                &CoreError::Provider(
                    "Anthropic API key is not configured; store a credential for anthropic or set its api_key_env".into()
                ),
                Some("Anthropic")
            ),
            "Anthropic is not connected. Connect it with an API key or by signing in, then try again."
        );
    }

    #[test]
    fn a_model_on_ollama_that_cannot_do_the_work_says_what_to_choose() {
        let mut gemma = model_info("gemma3:latest", 32_768);
        gemma.tools = false;
        let mut cloud = model_info("gpt-oss:120b-cloud", 32_768);
        cloud.display_name = "gpt-oss:120b-cloud".into();
        let ollama = haarness_protocol::ProviderInfo {
            id: "ollama".into(),
            name: "Ollama".into(),
            authenticated: true,
            models: vec![
                gemma.clone(),
                cloud.clone(),
                model_info("llama3:8b", 8_192),
                model_info("qwen3:8b", 32_768),
                model_info("gpt-oss:20b", 32_768),
            ],
        };
        let words = |error: &str, model: &str| {
            super::describe_local_model_failure(
                &CoreError::Provider(error.into()),
                &ollama,
                model,
                true,
            )
        };
        // Not downloaded: how to get it, and what is here.
        assert_eq!(
            words("HTTP 404 Not Found: model 'qwen2.5-coder:14b' not found. Download it with `ollama pull qwen2.5-coder:14b`, or pick a model you have.", "qwen2.5-coder:14b").as_deref(),
            Some("qwen2.5-coder:14b isn't downloaded in Ollama. Download it with `ollama pull qwen2.5-coder:14b`, then send your message again, or choose a model you have, such as qwen3:8b or gpt-oss:20b.")
        );
        // A cloud model while this computer's Ollama isn't signed in: not a
        // key to connect again.
        assert_eq!(
            words("HTTP 401 Unauthorized: Unauthorized", "gpt-oss:120b-cloud").as_deref(),
            Some(
                "gpt-oss:120b-cloud runs on Ollama's cloud, and the Ollama on this computer isn't signed in to ollama.com. Sign in with `ollama signin`, then send your message again. Or choose a model that runs on this computer, such as qwen3:8b or gpt-oss:20b."
            )
        );
        // A model without tools would only pretend to have done the work.
        assert_eq!(
            words("gemma3:latest does not support tools", "gemma3:latest").as_deref(),
            Some(
                "gemma3:latest can't use tools in Ollama, so it can't read, change or run anything in your project. Choose one that can for this chat, such as qwen3:8b or gpt-oss:20b."
            )
        );
        // Too short for the instructions and tools, even compacted: models
        // with more room, not the short one.
        assert_eq!(
            words("HTTP 400 Bad Request: request (14112 tokens) exceeds the available context size (8192 tokens), try increasing it", "llama3:8b").as_deref(),
            Some("llama3:8b reads at most 8,192 tokens at once here, fewer than Haarness's instructions, tools and this message take. Choose one with a longer context for this chat, such as qwen3:8b or gpt-oss:20b.")
        );
        // A turn that read one large file after another outgrew the window
        // though the chat was compacted as often as a turn may: not the
        // instructions and the message. gpt-oss on Ollama, 2026-11-10.
        let refused = "HTTP 400 Bad Request: request (40069 tokens) exceeds the available context size (32768 tokens), try increasing it";
        let outgrown = super::outgrew_window(
            CoreError::Provider(refused.into()),
            super::MAX_COMPACTIONS_UNANSWERED,
        );
        assert!(matches!(
            super::outgrew_window(CoreError::Provider(refused.into()), super::MAX_COMPACTIONS_UNANSWERED - 1),
            CoreError::Provider(words) if words == refused
        ));
        assert_eq!(
            super::describe_local_model_failure(&outgrown, &ollama, "gpt-oss:20b", true).as_deref(),
            Some(
                "gpt-oss:20b reads at most 32,768 tokens at once here, and this turn outgrew that while it ran, though the chat was compacted 4 times to make room. Ask for less in one message, such as fewer or smaller files at a time, or start a new chat."
            )
        );
        // Any other provider's refusal reads as it did.
        let claude = super::outgrew_window(
            CoreError::Provider(
                "HTTP 400 Bad Request: prompt is too long: 210000 tokens > 200000 maximum".into(),
            ),
            super::MAX_COMPACTIONS_UNANSWERED,
        );
        assert!(super::describe_error(&claude, Some("Anthropic")).contains("prompt is too long"));
        assert!(!super::describe_error(&claude, Some("Anthropic")).contains("outgrew"));
        // With nothing here that could, one to download.
        let alone = haarness_protocol::ProviderInfo {
            models: vec![gemma, cloud],
            ..ollama.clone()
        };
        assert_eq!(
            super::describe_local_model_failure(
                &CoreError::Provider("gemma3:latest does not support tools".into()),
                &alone,
                "gemma3:latest",
                true,
            )
            .as_deref(),
            Some(
                "gemma3:latest can't use tools in Ollama, so it can't read, change or run anything in your project. Download one that can with `ollama pull qwen3:8b`, then choose it for this chat."
            )
        );
        // The model that started a child agent reads only what happened.
        assert_eq!(
            super::describe_local_model_failure(
                &CoreError::Provider("gemma3:latest does not support tools".into()),
                &ollama,
                "gemma3:latest",
                false,
            )
            .as_deref(),
            Some(
                "gemma3:latest can't use tools in Ollama, so it can't read, change or run anything in your project."
            )
        );
        // Nothing at all back from a small model.
        assert_eq!(
            words(
                "the local model sent back an empty reply: smollm2:1.7b",
                "smollm2:1.7b"
            )
            .as_deref(),
            Some(
                "smollm2:1.7b sent back an empty reply. A small model often can't follow Haarness's instructions and tools. Choose a larger one that uses them for this chat, such as qwen3:8b or gpt-oss:20b."
            )
        );
        // A picture: models here that read them and use tools.
        let mut seeing = model_info("qwen3-vl:8b", 32_768);
        seeing.images = true;
        let with_eyes = haarness_protocol::ProviderInfo {
            models: [ollama.models.clone(), vec![seeing]].concat(),
            ..ollama.clone()
        };
        assert_eq!(
            super::describe_local_model_failure(
                &CoreError::Provider("qwen3:8b doesn't read images. Send the message without the picture, or switch to a model that reads them.".into()),
                &with_eyes,
                "qwen3:8b",
                true,
            )
            .as_deref(),
            Some("qwen3:8b doesn't read images. Send the message without the picture, or switch to a model that reads them, such as qwen3-vl:8b.")
        );
        assert_eq!(
            words(
                "qwen3:8b doesn't read images. Send the message without the picture, or switch to a model that reads them.",
                "qwen3:8b"
            ),
            None
        );
        // Other failures, and other providers, keep their own words.
        assert_eq!(
            words("HTTP 500 Internal Server Error: boom", "qwen3:8b"),
            None
        );
        let other = haarness_protocol::ProviderInfo {
            id: "openai".into(),
            ..ollama
        };
        assert_eq!(
            super::describe_local_model_failure(
                &CoreError::Provider("HTTP 401 Unauthorized: Unauthorized".into()),
                &other,
                "gpt-oss:120b-cloud",
                true,
            ),
            None
        );
    }

    #[test]
    fn a_retired_model_is_named_with_models_the_provider_lists_now() {
        let mut opus = model_info("claude-opus-6", 1_000_000);
        opus.display_name = "Claude Opus 6".into();
        let catalog = haarness_protocol::ProviderInfo {
            id: "anthropic".into(),
            name: "Anthropic".into(),
            authenticated: true,
            models: vec![
                model_info("embed-1", 8_000),
                opus,
                model_info("claude-sonnet-6", 1_000_000),
                model_info("claude-haiku-6", 200_000),
                model_info("claude-fable-6", 200_000),
            ],
        };
        let not_found = CoreError::Provider(
            r#"HTTP 404 Not Found: {"type":"error","error":{"type":"not_found_error","message":"model: claude-opus-4-1"}}"#.into(),
        );
        assert_eq!(
            super::describe_model_refusal(&not_found, &catalog, "claude-opus-4-1", true).as_deref(),
            Some(
                "Anthropic no longer offers Claude Opus 4.1. Choose another model for this chat, such as Claude Opus 6, Claude Sonnet 6 or Claude Haiku 6."
            )
        );
        assert_eq!(
            super::describe_model_refusal(&not_found, &catalog, "claude-opus-4-1", false)
                .as_deref(),
            Some(
                "Anthropic no longer offers Claude Opus 4.1. It lists Claude Opus 6, Claude Sonnet 6 and Claude Haiku 6 among others."
            )
        );
        for raw in [
            "HTTP 404 Not Found: The model `gpt-0` does not exist or you do not have access to it.",
            r#"HTTP 400 Bad Request: {"error":{"message":"The model `gpt-0` does not exist","code":"model_not_found"}}"#,
            "HTTP 400 Bad Request: models/gpt-0 is not found for API version v1beta, or is not supported for generateContent.",
            "HTTP 400 Bad Request: The provided model identifier is invalid.",
        ] {
            let refused = super::describe_model_refusal(
                &CoreError::Provider(raw.into()),
                &catalog,
                "gpt-0",
                true,
            );
            assert!(
                refused
                    .as_deref()
                    .is_some_and(|words| words.starts_with("Anthropic no longer offers GPT-0.")),
                "{raw}: {refused:?}"
            );
        }
        // A model the list still has, or a refusal of a setting, keeps the
        // provider's own words.
        assert!(
            super::describe_model_refusal(&not_found, &catalog, "claude-opus-6", true).is_none()
        );
        for raw in [
            "HTTP 400 Bad Request: reasoning_effort ultra is not supported with gpt-0.",
            "HTTP 400 Bad Request: image input is not supported by gpt-0.",
            "HTTP 404 Not Found",
            "HTTP 500 Internal Server Error: upstream gpt-0 unknown failure",
        ] {
            let error = CoreError::Provider(raw.into());
            assert!(
                super::describe_model_refusal(&error, &catalog, "gpt-0", true).is_none(),
                "{raw}"
            );
        }
        // An empty list still names the model.
        let empty = haarness_protocol::ProviderInfo {
            models: Vec::new(),
            ..catalog.clone()
        };
        assert_eq!(
            super::describe_model_refusal(&not_found, &empty, "claude-opus-4-1", true).as_deref(),
            Some("Anthropic no longer offers Claude Opus 4.1. Choose another model for this chat.")
        );
        // Copilot's own refusal stays one message and names models too.
        let copilot = haarness_protocol::ProviderInfo {
            id: "github-copilot".into(),
            name: "GitHub Copilot".into(),
            authenticated: true,
            models: vec![
                model_info("gpt-5.4", 400_000),
                model_info("claude-sonnet-5-5", 200_000),
            ],
        };
        let unsupported = CoreError::Provider(
            r#"HTTP 400 Bad Request: {"error":{"message":"The requested model is not supported.","code":"model_not_supported","param":"model","type":"invalid_request_error"}}"#.into(),
        );
        assert_eq!(
            super::describe_model_refusal(&unsupported, &copilot, "gpt-5.4", true).as_deref(),
            Some(
                "Your GitHub Copilot plan doesn't include GPT-5.4. Choose another model, such as Claude Sonnet 5.5, or turn it on at github.com/settings/copilot."
            )
        );
    }

    #[test]
    fn googles_refusals_of_a_model_for_this_key_say_what_to_choose_instead() {
        let mut flash = model_info("gemini-3.8-flash", 1_048_576);
        flash.display_name = "Gemini 3.8 Flash".into();
        let mut argon = model_info("gemini-4-argon", 1_048_576);
        argon.display_name = "Gemini 4 Argon".into();
        let mut pro = model_info("gemini-2.5-pro", 1_048_576);
        pro.display_name = "Gemini 2.5 Pro".into();
        let catalog = haarness_protocol::ProviderInfo {
            id: "gemini".into(),
            name: "Google Gemini".into(),
            authenticated: true,
            models: vec![
                argon,
                flash,
                model_info("gemini-3.1-pro-preview", 1_048_576),
                pro,
            ],
        };
        // As Gemini answers a key made after Gemini 2.5 was retired, though
        // its model list still has it.
        let retired = CoreError::Provider(
            "HTTP 404 Not Found: This model models/gemini-2.5-pro is no longer available to new users. Please update your code to use models/gemini-3.1-pro-preview for the latest features and improvements. We recommend you to use the Interactions API (https://aistudio.google.com/docs/get-started).".into(),
        );
        assert_eq!(
            super::describe_model_refusal(&retired, &catalog, "gemini-2.5-pro", true).as_deref(),
            Some(
                "Google Gemini no longer offers Gemini 2.5 Pro to new accounts. Choose another model for this chat, such as Gemini 3.1 Pro Preview."
            )
        );
        assert_eq!(
            super::describe_model_refusal(&retired, &catalog, "gemini-2.5-pro", false).as_deref(),
            Some("Google Gemini no longer offers Gemini 2.5 Pro to new accounts.")
        );
        // A free-tier key and a model its tier leaves out: Google names a
        // wait, but the turn fails at once and says what to do.
        let left_out = CoreError::Provider(
            "HTTP 429 Too Many Requests: You exceeded your current quota, please check your plan and billing details. For more information on this error, head to: https://ai.google.dev/gemini-api/docs/rate-limits. To monitor your current usage, head to: https://ai.dev/rate-limit. \n* Quota exceeded for metric: generativelanguage.googleapis.com/generate_content_free_tier_input_token_count, limit: 0, model: gemini-4-argon\n* Quota exceeded for metric: generativelanguage.googleapis.com/generate_content_free_tier_requests, limit: 0, model: gemini-4-argon\nPlease retry in 41.236318127s.".into(),
        );
        assert_eq!(super::retry_delay(&left_out, 1), None);
        assert_eq!(
            super::describe_model_refusal(&left_out, &catalog, "gemini-4-argon", true).as_deref(),
            Some(
                "Google Gemini's free tier doesn't include Gemini 4 Argon. Choose another model for this chat, such as Gemini 3.8 Flash, or turn on billing for this API key's project in Google AI Studio."
            )
        );
        assert_eq!(
            super::describe_model_refusal(&left_out, &catalog, "gemini-4-argon", false).as_deref(),
            Some("Google Gemini's free tier doesn't include Gemini 4 Argon for this API key.")
        );
        // A day's allowance used up comes back the next day.
        let daily = CoreError::Provider(
            "HTTP 429 Too Many Requests: You exceeded your current quota, please check your plan and billing details. \n* Quota exceeded for metric: generativelanguage.googleapis.com/generate_content_free_tier_requests, limit: 20, model: gemini-3.8-flash\nPlease retry in 21h16m10.222s.".into(),
        );
        assert_eq!(super::retry_delay(&daily, 1), None);
        assert_eq!(
            super::describe_model_refusal(&daily, &catalog, "gemini-3.8-flash", true).as_deref(),
            Some(
                "This API key has used up Google Gemini's free allowance for Gemini 3.8 Flash, which comes back in about 21 hours. Choose another model for this chat, or turn on billing for this API key's project in Google AI Studio."
            )
        );
        // Groq's day of tokens for one model used up: other models have
        // their own, and its words name the organization, which stays out.
        let mut oss = model_info("openai/gpt-oss-120b", 131_072);
        oss.display_name = "GPT OSS 120B".into();
        let mut qwen = model_info("qwen/qwen3.8-27b", 131_072);
        qwen.display_name = "Qwen3.8-27B".into();
        let groq = haarness_protocol::ProviderInfo {
            id: "groq".into(),
            name: "Groq".into(),
            authenticated: true,
            models: vec![oss, qwen],
        };
        let day = CoreError::Provider(
            "HTTP 429 Too Many Requests: [rate_limit_exceeded] Rate limit reached for model `openai/gpt-oss-120b` in organization `org_01abc` service tier `on_demand` on tokens per day (TPD): Limit 200000, Used 198971, Requested 6952. Please try again in 42m38.736s. Need more tokens? Upgrade to Dev Tier today at https://console.groq.com/settings/billing".into(),
        );
        assert_eq!(super::retry_delay(&day, 1), None);
        assert_eq!(
            super::describe_model_refusal(&day, &groq, "openai/gpt-oss-120b", true).as_deref(),
            Some(
                "This account has used today's 200,000 tokens for GPT OSS 120B on Groq, which come back in about 43 minutes. Choose another model for this chat, such as Qwen3.8-27B, or upgrade the plan at https://console.groq.com/settings/billing."
            )
        );
        assert_eq!(
            super::describe_model_refusal(&day, &groq, "openai/gpt-oss-120b", false).as_deref(),
            Some(
                "This account has used today's 200,000 tokens for GPT OSS 120B on Groq, which come back in about 43 minutes."
            )
        );
        // A minute's limit names a wait a turn sits out: not a day's.
        assert_eq!(
            super::describe_model_refusal(
                &CoreError::Provider("HTTP 429 Too Many Requests: Rate limit reached for model `openai/gpt-oss-120b` in organization `org_01abc` service tier `on_demand` on tokens per minute (TPM): Limit 8000, Used 7682, Requested 6196. Please try again in 40.8s.".into()),
                &groq,
                "openai/gpt-oss-120b",
                true
            ),
            None
        );
        // A per-minute allowance is waited out; when the turn still fails it
        // says so plainly.
        let minute = CoreError::Provider(
            "HTTP 429 Too Many Requests: You exceeded your current quota. \n* Quota exceeded for metric: generativelanguage.googleapis.com/generate_content_free_tier_requests, limit: 5, model: gemini-3.8-flash\nPlease retry in 17.197029539s.".into(),
        );
        assert!(super::retry_delay(&minute, 1).is_some());
        assert_eq!(
            super::describe_model_refusal(&minute, &catalog, "gemini-3.8-flash", true).as_deref(),
            Some(
                "Gemini 3.8 Flash is at the limit of Google Gemini's free tier for this API key. Wait a minute and send the message again, choose another model, or turn on billing for this API key's project in Google AI Studio."
            )
        );
        // Any provider's quota of nothing is not waited for; other limits
        // and counts that are not whole numbers are read as before.
        assert_eq!(
            super::retry_delay(
                &CoreError::Provider(
                    "HTTP 429: quota exceeded, limit: 0. Please retry in 5s.".into()
                ),
                1
            ),
            None
        );
        assert!(
            super::retry_delay(
                &CoreError::Provider(
                    "HTTP 429: rate limit, limit: 0.5 per second. Please retry in 5s.".into()
                ),
                1
            )
            .is_some()
        );
    }

    /// Google refuses a free-tier key that has used a model's 20 requests
    /// of the day with "Please retry in 11.6s", the wait a minute's limit
    /// names too; the quota's id says it is a day's. A turn sat out four
    /// such waits and then said "Wait a minute and send the message again".
    #[test]
    fn a_day_of_google_quota_used_up_is_not_waited_for_and_says_when_it_returns() {
        let mut flash = model_info("gemini-3.8-flash", 1_048_576);
        flash.display_name = "Gemini 3.8 Flash".into();
        let mut older = model_info("gemini-3.7-flash", 1_048_576);
        older.display_name = "Gemini 3.7 Flash".into();
        let mut argon = model_info("gemini-4-argon", 1_048_576);
        argon.display_name = "Gemini 4 Argon".into();
        let catalog = haarness_protocol::ProviderInfo {
            id: "gemini".into(),
            name: "Google Gemini".into(),
            authenticated: true,
            models: vec![flash, argon, older],
        };
        let refusal = |tier: &str, quota: &str| {
            CoreError::Provider(format!(
                "HTTP 429 Too Many Requests: You exceeded your current quota, please check your plan and billing details. For more information on this error, head to: https://ai.google.dev/gemini-api/docs/rate-limits. To monitor your current usage, head to: https://ai.dev/rate-limit. \n* Quota exceeded for metric: generativelanguage.googleapis.com/generate_content_{tier}_requests, limit: 20, model: gemini-3.8-flash\nPlease retry in 11.615098148s.\n* Quota id: {quota}"
            ))
        };
        let daily = refusal(
            "free_tier",
            "GenerateRequestsPerDayPerProjectPerModel-FreeTier",
        );
        assert_eq!(super::retry_delay(&daily, 1), None);
        let words =
            super::describe_model_refusal(&daily, &catalog, "gemini-3.8-flash", true).unwrap();
        let (said, renews) = words
            .split_once(", which comes back at midnight Pacific time, in about ")
            .unwrap();
        assert_eq!(
            said,
            "This API key has used up today's free allowance for Gemini 3.8 Flash on Google Gemini"
        );
        assert!(
            renews.ends_with(
                ". Choose another model for this chat, such as Gemini 3.7 Flash, or turn on billing for this API key's project in Google AI Studio."
            ),
            "{words}"
        );
        assert!(
            super::describe_model_refusal(&daily, &catalog, "gemini-3.8-flash", false)
                .unwrap()
                .starts_with("This API key has used up today's free allowance for Gemini 3.8 Flash on Google Gemini, which comes back at midnight Pacific time, in about ")
        );
        // A paid project's day of quota is not waited for either.
        let paid = refusal("paid_tier", "GenerateRequestsPerDayPerProjectPerModel");
        assert_eq!(super::retry_delay(&paid, 1), None);
        let words =
            super::describe_model_refusal(&paid, &catalog, "gemini-3.8-flash", true).unwrap();
        assert!(
            words.starts_with("This API key's project has used today's quota for Gemini 3.8 Flash on Google Gemini, which comes back at midnight Pacific time, in about "),
            "{words}"
        );
        assert!(
            words.ends_with(". Choose another model for this chat, such as Gemini 4 Argon or Gemini 3.7 Flash, or raise the project's limits in Google AI Studio."),
            "{words}"
        );
        // A minute's quota names the same wait and is still waited out.
        let minute = refusal(
            "free_tier",
            "GenerateRequestsPerMinutePerProjectPerModel-FreeTier",
        );
        assert!(super::retry_delay(&minute, 1).is_some_and(|wait| {
            wait > std::time::Duration::from_secs(12) && wait < std::time::Duration::from_secs(13)
        }));
        assert!(
            super::describe_model_refusal(&minute, &catalog, "gemini-3.8-flash", true)
                .unwrap()
                .starts_with("Gemini 3.8 Flash is at the limit of Google Gemini's free tier")
        );
    }

    #[test]
    fn google_renews_a_days_quota_at_midnight_pacific_time() {
        let at = |text: &str| {
            chrono::DateTime::parse_from_rfc3339(text)
                .unwrap()
                .with_timezone(&Utc)
        };
        let hours = |text: &str| super::until_pacific_midnight(at(text)).as_secs_f64() / 3600.0;
        // Daylight time (UTC-7): midnight is 07:00 UTC.
        assert!((hours("2026-07-01T06:00:00Z") - 1.0).abs() < 1e-9);
        assert!((hours("2026-07-01T07:00:00Z") - 24.0).abs() < 1e-9);
        // Standard time (UTC-8): midnight is 08:00 UTC.
        assert!((hours("2026-11-10T14:00:00Z") - 18.0).abs() < 1e-9);
        assert!((hours("2026-01-15T07:30:00Z") - 0.5).abs() < 1e-9);
        // Daylight time ends on the first Sunday of November (2026-11-01)
        // and begins on the second Sunday of March (2026-03-08).
        assert!((hours("2026-10-31T20:00:00Z") - 11.0).abs() < 1e-9);
        assert!((hours("2026-11-01T10:00:00Z") - 22.0).abs() < 1e-9);
        assert!((hours("2026-03-08T11:00:00Z") - 20.0).abs() < 1e-9);
    }

